COLLDATA("tadabburur","ur",[[513,"§الفتح\ndeeds\nیہ دعا پڑھئے: (اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِىْ عَلٰى دِيْنِكَ) اے الله ! دلوں كو پھیرنے والے، میرے دل كو دین اسلام پر ثابت قدم ركھ.\nكسى صحابى كى سیرت تحریر كیجئے اور اسے لوگوں كو میسیج كردیجئے تاكہ صحابہ كے فضائل واضح ہوسكے.\nكہئے: (اَللّٰهُمَّ أَصْلِحْ لِي قَلْبِىْ) اے الله ! میرے دل كى اصلاح فرما.\nguid\nجو شخص الله كے اوامر واحكام كو بجالائے گا، الله تعالىٰ اسكى معاشى ودنیاوى زندگى میں آسانى پیدا كرےگا.\nبندوں كےساتھ الله كى آسانى ورحمت كے بارے میں غور كیجئے.\nصحابہ كرام كى فضیلت بالخصوص بیعت رضوان میں شریك صحابہ كرام كى فضیلت ، الله ان سے راضى ہوگیا اور ان كےدلوں كو پاك صاف كردیا، اب جو ان لوگوں كو گالى دےگا یا ان پر لعنت بھیجےگا وه قرآن كو جھٹلائےگا.\nrefl\nلَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ\nالله تعالىٰ نے تركِ جہاد كیلئے چند اعذار بیان كیے ہیں، بعض اعذار لازمى ودائمى ہیں جیسے:اندھا پن اور لنگڑا پن ، اور بعض اعذار عارضى ہیں جیسے بعض بیماریوں كا آجانا پھر ختم ہوجانا بیمار مسلمان دائمى و لازمى مریض كے حكم میں ہے یہاں تك كہ شفایاب ہوجائے۔(ابن كثیر: ۴؍۱۹۳)\nجب جہاد فرض ہوجائے تو کس عذر كى بنا پر جہاد ترك كیا جاسكتاہے؟آیت كى روشنى میں بیان كیجئے.\nوَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا ١٧\nالله تعالىٰ دنیا میں ذلت ورسوائى مسلط كردےگا اور آخرت میں جہنم مقدر كردےگا۔ (ابن كثیر: ۴؍۱۹۳)\nكیا دردناك عذاب صرف اور صرف آخرت كا حصہ ہے؟\n۞لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا ١٨\nالله كے رسول صلی اللہ علیہ وسلم نے فرمایا: درخت كےنیچے بیعت كرنے والوں میں سے كوئى بھى جہنم میں نہیں جائےگا (فعلم ما في قلوبهم) یعنى الله تعالىٰ ان كے ایمان كى سچائى اور جہاد كیلئے ان كے عزم مصمم كى صداقت سےبخوبى واقف ہے۔ (وأثابهم فتحًا قريبًا) یعنى الله تعالىٰ نے انہیں فتح خیبر یا فتح مكہ سے نوازا۔ پہلا قول زیادہ مشہور ہے، یعنی اللہ نے یہ ثواب آخرت کے ثواب کے علاوہ بیعتِ رضوان کے عوض عطاکیا۔(ابن جزى: ۲؍۳۴۹)\nآپ اس آیت سے اس شخص پر کیسے رد کریں گے جس کا اعتقاد ہے کہ سات صحابہ کے علاوہ دیگر تمام صحابہ کافر و مرتد ہوگئے تھے ؟\nوَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا\nاللہ تعالیٰ نے تمہارے لئے ایک عمدہ تدبیر اپنائی وہ یہ کہ اس نے بڑی بڑی چیزوں کو ان کے غیرظاہری اسبابجیسا کہ لوگوں کا نظریہ ہے کے ذریعہ نوازا، لہٰذا مومنوں كو دشمنوں كى كثرت وقوت سے خوفزده نہیں ہونا چاہئے، كیونكہ مومن بندوں كو الله كى معیت اتباع بالاحسان میں مضمر ہے جس كى بنیاد اس ایمان کے رسوخ پرہے، جس پر حکم معلق ہے کہ جہاں معلّق علیہ پایاجائے گا وہیں معلق بھی پایاجائے گا اور وہ الله كى مدد ونصرت خواہ یہ ظاہری اسباب کے ذریعہ ہو یا مخفی اسباب کے ذریعہ۔ (البقاعى: ۱۸؍۳۱۹)\nالله تعالىٰ نے مومنوں كیلئے جو كچھ مقدر كردیا ہے وه بہت بہتر ہے بنسبت مومنوں كے اپنے انتخابات سے، آیت كى روشنى میں اس كى وضاحت كیجئے.\nوَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ\nالله تعالىٰ نے اس آیت میں قیامت تك كیلئے مومنوں سے بہت سارى غنیمتوں كا وعده كیا ہے جنہیں وه لوگ ان كے محدود اوقات میں پالیں گے۔(الشوكانى: ۵؍۵۱)\nاس آیت سےمومنوں كے لئے الله كى تكریم كى وضاحت كیجئے.\nوَكَفَّ أَيۡدِيَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةٗ لِّلۡمُؤۡمِنِينَ\n(وكف أيدي الناس عنكم) یہ اس وقت ہوا تھا جب نبى كریم صلی اللہ علیہ وسلم نے خیبر پر چڑھائى كى اور اس كا محاصره كر لیا تو بنى اسد وغطفان كے بعض قبیلوں نے مدینہ میں مسلمانوں كے اہل وعیال پر حملہ كرنے كا اراده كرلیا، ایسے وقت میں الله تعالىٰ نے ان كے دلوں میں رعب پیدا كركےان كے ہاتھ روک لئے۔(البغوى: ۴؍۱۷۵)\n(لوگوں کے ہاتھ روک لئے) سے کیا مراد ہے؟\nسُنَّةَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ٢٣\nاور جب اللہ تعالیٰ نے اِس سنت و عادت کو ماضی میں رہنے کی بات کی تو اس نے اسے مستقبل کے ہرزمانہ میں جاری و ساری رہنے کے لئے اپنے اس قول کا (ولن تجد لسنة الله تبديلًا) ذکرکیا کیونکہ پچھلی قوموں وزمانوں كے واقعات اور پیغمبروں كے ذریعہ دئے گئے بیانات گواه ہیں كہ الله تعالىٰ نے اہل ایمان كى (ہمیشہ) مدد كى ہے جن سے معلوم ہورہا ہے کہ كوئى بھى اس الٰہى اراده كے بیچ حائل نہیں ہوسكتا۔ (ابن عاشور: ۲۶؍۱۸۳)\nآیت (ولن تجد لسنة الله تبديلًا) كے ذریعہ تاكید كا فائده بتائیے.\nwords\nحَرَجٌترك جهاد كا گناه.\nيُبَايِعُونَكَوه آپ كي بيعت كرتے هيں / مراد بيعت رضوان هے.\nالسَّكِينَةَاطمينان اور ثبات.\nفَتحًا قَرِيبًاقريبي فتح / فتح خيبر.\nأَحَاطَ اللهُ بِهَاالله تعاليٰ اس پر قادر هيں۔اوريقين اس نے تمهارے دشمنوں كو وعيدسنائي هے.\nلَوَلَّوُا الأَدبَارَوه ضرور شكست كھاتے؛ اور پيٹھ پھير كر بھاگ جاتے.\nسُنَّةَ اللهِالله تعاليٰ كا اپنے لشكروں كي مدد كا طريقه."],[514,"§الفتح\ndeeds\nكہئے: (اَللّٰهُمَّ اَنْزِلِ السَّكِيْنَةَ عَلٰى قَلْبِىْ ) اے الله ! میرے دل پر سكون و اطمینان نازل فرما.\nصرف اسلامى اخوت كى بنا پر ایك مسلمان بھائى كى مدد كیجئے جس سے نہ آپ كى رشتہ دارى ہے اور نہ ہى كوئى تعلق.\nمستقبل كےبارے میں گفتگو پر(إن شاء الله) ضرور كہئے.\nguid\nالله تعالىٰ كے نزدیك خونِ مسلم كى عظیم حرمت کیونکہ الله تعالىٰ نے مكہ كےچند مومنوں كى خاطر اہل مكہ كے ساتھ لڑائى اور عذاب كو منع كردیا ہے.\nبعض بھلائیوں كى تاخیر میں الله كى عظیم حكمت پنہاں ہے مثلا فتح مكہ.\nالله تعالىٰ نے صحابہ كرام(رضی اللہ عنہم) كى عزت افزائى كى ہے، آپ بھى ان كے ادب كا خیال ركھئے، اور رافضى وغیره جو صحابہ كرام سے عداوت ركھتےہیں آپ بھى ایسے لوگوں سے عداوت ركھئے.\nrefl\nوَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا ٢٥\nبسا اوقات مشكل وممنوع چیزوں میں انسان کو سعادت وخوش بختى نظر آتى ہے حالانكہ اس كا باطن زہر آلود ہوتا ہے، تو الله تعالىٰ كا ان چیزوں سے منع كرنا باعثِ رحمت ہے گرچہ بظاہر عذاب لگ رہا ہے ، لہذا الله كى قضاء وقدر پر سرتسلیم خم كیجئے لیكن خیر كو پانے كى بھر پور كوشش كیجئے اور اس كےلئے حریص رہئے اور اس كے كھو جانے پر شرمند ه ہوئیے لیكن قضائے الہى پر اعتراض سے بچئے، اور آیت میں ایك فائده یہ بھی ہے كہ الله تعالىٰ مومنوں كى خاطر كافروں سے عذاب كو روك لیتاہے۔(البقاعى: ۱۸؍۳۲۹)\nقضائے الٰہی حكمت ورحمت كےساتھ مربوط ہے،آیت سے اس كى وضاحت كیجئے.\nإِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ\nحمیت كى نسبت جاہلیت كى طرف اس كى حقارت وقباحت كو اجاگر كرنے كى غرض سےہے كیونكہ یہ اہل جاہلیت كے اخلاق میں سےہے، اور اصطلاحِ قرآن میں قابلِ مذمت نسبت ہے، قرآن میں ہے : ﴿يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِ﴾ [آل عمران: ۱۵۴] وه الله تعالىٰ كے ساتھ ناحق جہالت بھرى بدگمانیاں كررہے تھے۔ اور﴿أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَ﴾ [المائده: ۵۰] كیا یہ لوگ پھر سے جاہلیت كا فیصلہ چاہتےہیں۔ (ابن عاشور: ۲۶؍۱۹۴)\n(حمیت )كى نسبت جاہلیت كى طرف كرنے كا فائده بتائیے.\nفَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ\nاس سكون كاثمره وفائده یہ ہے كہ خبر ِالٰہى پر مكمل یقین واطمینان حاصل ہوگا اور اوامر واحكام كى اطاعت وفرمانبردارى ہوگى ، كوئى شبہ خبر میں شك پیدا نہیں كرےگا اور نہ ہى كوئى چاہت واراده اطاعت ِاوامر میں رخنہ ڈالےگا، دلوں میں پیدا ہونے والے خدشات ، بدگمانیاں شیطانى وسوسے آئیں گے ، اور یہ سب بنده كیلئے ابتلاء وامتحان كى چیزیں ہیں ان كو جھٹكنے اور دور كرنے اور دلوں میں جگہ نہ دینے سے بنده كا ایمان مضبوط ہوگا، الله كےنزدیك اس كے درجات بلند ہوں گے، لہٰذا مومن یہ تصور نہ کرے کہ ان سب سے ان کے مقام و مرتبے کم ہوجائیں گے۔ (ابن القیم: ۲؍۴۵۹)\nمومنوں كےدلوں پر سكینت نازل كرنے كا فائده كیا ہے؟\nإِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ\nجب (جاہلى حمیت )جاہلیت سے بھرپور اقوال وافعال كو جنم دیتی ہےتو الله تعالىٰ نے اس كا مقابلہ كرنے كیلئے مومنوں كے دلوں میں سكینت ڈال دی ہے اور ان كى زبانوں پر كلمۂ تقوىٰ جارى كردیاہے یعنی (سكینت) حمیت جاہلیہ كے مقابلےكیلئے اور كلمۂ تقوىٰ فسق وفجور كے مقابلے كیلئے ہے۔ (ابن القیم: ۲؍۴۵۸- ۴۵۹)\nمومنوں كےدلوں پر انعام الٰہى سكون اور زبانوں پر كلمۂ تقوى كا سبب كیا ہے؟\nوَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ\nكلمۂ تقوىٰ (لا الہ الا الله) ہے ، اسے تقوىٰ كى طرف منسوب كیا گیا ہے، كیونكہ اسى كےذریعے شرك سے بچاجاسكتاہے، یعنى یہ كلمہ ہر تقوىٰ كى ا صل وبنیاد ہے۔ (الألوسى: ۱۳؍۲۷۱)\nكلمۂ تقوى سے كیا مراد ہے؟ اور ہمیشہ مومن اس كا التزام كیوں كرے؟\nلَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ\nاس میں اشاره ہے كہ مسجدِ حرام میں مسلمان الله كى مشیئت سے داخل ہوں گے نہ كہ اپنى طاقت وتدبیر سے۔ (الألوسى: ۱۳؍۲۷۳)\nآیت میں مشیئت كى قید كا كیا فائده ہے؟\nهُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ\nكئى جگہوں پر قرآن نے علمى نظری قوت اور عملى قوتِ ارادی كى افادیت كا ذكر كیا ہے، بطور نمونہ الله كا ارشاد ہے: (هو الذي أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله) (الهدى) سے مراد علمِ كامل اور دین ِحق سے مراد عملِ كامل ہے، جیسا كہ اس آیت میں ہے: ﴿أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰر﴾ [ص: ۴۵] ہاتھوں اور آنكھوں والے۔ (ابن تیمیہ: ۶؍۳۸)\nمسلمان دو طرح كى قوت كے محتاج ہیں، وه دونوں كیا ہیں؟\nwords\nبِبَطنِ مَكَّةَمكه كے وسط ميں۔ بمقام حديبيه ؛ مكه كے قريب.\nأَظفَرَكُمتمهيں ان پر قدرت دي ۔ تم نے انهيں گرفتار كرليا۔ وه اسي لوگ تھے.\nمَعكُوفًامحبوس / قيدي.\nمَحِلَّهُوه مقام جهاں قرباني كو نحر كرنا حلال هو جاتا هے.\nمَعَرَّةٌگناه / عيب / تاوان.\nتَزَيَّلُوايه كمزور ان كفار سے جداگانه هيں.\nالحَمِيَّةَضد/ انفه."],[515,"§الفتح ، الحجرات\ndeeds\nاپنے دوستوں اور مسلمان بھائیوں سے مسكراكر ملئے اور انہیں سلام كیجئے، یہ بھى رحم دلى میں داخل ہے.\nآج كى نمازوں میں ركوع وسجدے طویل كیجئے.\nیہ دعا کیجئے: (اَللّٰهُمَّ اهْدِنِىْ لِأَحْسَنِ الْأَقْوَالِ وَالْأَعْمَالِ وَالْأَخْلَاقِ لَا يَهْدِیْ لِأَحْسَنِهَا إِلَّا أَنْتَ، وَجَنِّبْنِىْ سَيِّئَهَا لَا يُجَنِّبُنِىْ سَيِّئَهَا إِلَّا أَنْتَ) (اے اللہ مجھے اچھے اقوال و افعال اور اچھے اخلاق کی طرف رہنمائی فرما، ان کی طرف تیرے سوا کوئی رہنمائی نہیں کرسکتا، اور مجھے ان کے برے سے بچا، اور تیرے سوا مجھے کوئی ان سےبچا نہیں سکتا).\nguid\nآپ صلی اللہ علیہ وسلم كے متبعین كافروں پر سخت اور آپس میں رحم دل ہیں.\nآپ صلی اللہ علیہ وسلم كا مقام ومرتبہ بڑا اونچاہے، لہٰذ۱آپ صلی اللہ علیہ وسلم كا ادب ضرورى ہے، آپ صلی اللہ علیہ وسلم كانام آئے تو آپ صلی اللہ علیہ وسلم پر درود وسلام ضروربھیجیں.\nعقل ادب کا ساتھی ہے.\nrefl\nمُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ\nصحابہ كرام كےحق میں “سختى ونرمى” دو متضاد خصلتوں كو جمع كرنا اس بات كى طرف اشاره ہے كہ وه رائے میں اصالت اور عقل میں حكمت ودانائى ركھتےتھے، ان كے اخلاق واعمال حكمت وبھلائى پر مشتمل ہوتے تھے، ان نفوس (قدسیہ) پر تعریف وتحسین اور تجریح و تقبیح میں سے كسى خاص امر كا غلبہ نہیں ہوتا تھا، اور وه كسى عمل كى طرف انسانى فطرت وبے بصیرتى كى بنیاد پر كھینچےنہیں چلےجاتےتھے۔ (ابن عاشور: ۲۶؍۲۰۵)\nشدت ورحمت دونوں صفتوں كو جمع كرنے كا كیا فائده ہے؟\nوَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا\n(أشداء على الكفار) كافروں كى دشمنى میں مخلص ومحنتى تھے ، اور اس سلسلہ میں پورى كوشش صرف كرتے تھے (رحماء بينهم) یعنى ایك بدن كى مانند آپس میں محبت اور رحم كرنے والے تھے، اپنے لئے وہى پسند كرتے جو دوسروں كیلئے پسند كرتےتھے، یہ تعامل ان كا مخلوق كےساتھ تھا، اور خالق كےساتھ ان كا معاملہ یوں ہوتا تھا: (تراهم ركعًا سجدًا). یعنى بکثرت ركوع كرنے والے اور سجدے كرنے والےتھے ۔ (السعدى: ۷۹۵)\nصحابہ كافروں پر سخت اور مومنوں كیلئے رحم دل تھے، اس كے تذكرے كےبعد ان كى نمازوں كاحال كیوں بیان ہوا ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ١\nجب الله تعالىٰ نے صحابہ كرام كو آپ صلی اللہ علیہ وسلم كى آواز پر اپنى آوازوں كو مقدم كرنے سے منع فرمایا تو معقولات كو آپ كى حدیثوں اور شریعتوں پر مقدم كرنا كیسے جائز ہوگا۔ (ابن القیم: ۳؍۵)\nآیت میں اشاره ہے كہ عقلِ سلیم نقل صحیح كےتابع ہونا ضرورى ہے ، اس كى وضاحت كیجئے.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ١\nاس آیت سے یہ بات معلوم ہوتى ہے كہ كسى كے قول كو رسول صلی اللہ علیہ وسلم كے قول پر مقدم كرنا سخت ممنوع ہے، سنت رسول صلی اللہ علیہ وسلم جب كسى پر واضح ہوجائے تو اس كى پیروى لازم ہوگى اور اسے غیر سنت پر فوقیت دینا ضرورى ہوگا چاہے وه جو بھى ہو۔(السعدى: ۷۹۹)\nرسول صلی اللہ علیہ وسلم كى واضح وظاہر باتوں كے باوجود غیر رسول صلی اللہ علیہ وسلم كى باتوں كى پیروى كا كیا حكم ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ\nبعض علماء كرام نے آپ صلی اللہ علیہ وسلم كى قبر كےپاس آواز اونچى كرنے كو مكروه كہا ہے ، اور دیگر بعض علماء كرام نے اہل علم كى عزت وتكریم كى خاطر علمى مجلسوں میں آواز اونچى كرنے كو مكروه گردانا ہےچونکہ یہ انبیاء کے وارثین ہیں۔ (القرطبى: ۱۹؍۳۶۱)\nآیت كى عملى تطبیق بتائیے.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ\nآیت كریمہ كا ظاہرى معنى یہ ہے كہ انسان كاعمل كبھى كبھى غیر شعورى طورپر اكارت ہوجاتاہے۔ (الشنقیطى: ۷؍۴۰۳)\nاس آیت سے كیا آپ سمجھتے ہیں كہ انسان كا عمل كبھى كبھار غیر شعورى طورپر ضائع ہوجاتا ہے؟\nإِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ٤\nالله تعالىٰ نے ان کی مذمت فرمائى كہ وه عقل نہیں ركھتے كیونكہ انہوں نے الله كےرسول صلی اللہ علیہ وسلم كے ادب واحترام كو الله تعالیٰ سے نہیں سیکھا، نیز ادب كا برتنا عقل اور اہل ِعقل كى علامت ہے، یاد ركھئے كہ بندے كا باادب ہونا ،باادب كا پاس ولحاظ ركھنا اس كے عقل كا پتہ دیتاہے اور یہ بتاتا ہے كہ الله تعالىٰ نے اس كے ساتھ خیر كا اراده فرمایا ہے۔ (السعدی:۷۹۹)\nآیت كى روشنى میں ادب وعقل كے درمیان تعلق كو واضح كیجئے.\nwords\nسِيمَاهُمان كي نشاني.\nشَطأَهُاس كا تنا؛ اس كي فرع.\nفَآزَرَهُاس تنے كو مضبوط كيا.\nفَاستَغلَظَپس وه موٹا هوگيا۔ سخت هوگيا.\nفَاستَوَى عَلَى سُوقِهِوه مضبوط هوا؛ او راپنے تنے پر كھڑا هوگيا.\nلاَ تُقَدِّمُواقول و فعل ميں آگے نه بڑھو۔ اور الله اور اس كے رسول كے حكم كے خلاف نه كرو ۔ پس تم بدعا ت كا ارتكاب كر بيٹھو."],[516,"§الحجرات\ndeeds\nكسى دوست كى زیارت كیجئے یا اسكى حاجت پورى كرنے كیلئے اس كى مدد كیجئے اور اسے توفیق كى دعا دیجئے، تاكہ آپ اسلامى اخوت كےمقاصد پورے كرسكیں.\nجان پہچان كے مخالفین كے درمیان صلح كرادیجئے.\nاپنے دوست اور بھائى كو اس كے محبوب لقب یا صفت سےپكارئیے.\nguid\nایمان وعملِ صالح سے محبت كرنا اور كفر وفسق سے نفرت كرنا عطیۂ الٰہی ہے، وہ اپنے بندوں میں جسے چاہے اس سے نوازتا ہے ،سو آپ الله سے اسے مانگئے.\nاپنے تمام معاملات میں عدل وانصاف كولازم پكڑئیے.\nتوبہ اور الله كى طرف پلٹنے کو لازم پکڑئیے.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ ٦\nفاسق شخص كى خبر مشكوك یا موضوع ہوتى ہے ، اس لئے كہ اسكى دینى حمیت وغیرت كمزور ہوتى ہے اور دینى حمیت وغیرت كى كمزورى كى وجہ سے محظور وممنوع كو وه معمولى حیثیت دیتاہے؛ حتى كہ وه خبر وگواہى جس سے دوسروں یا مصالح عامہ كو نقصان پہونچ سكتاہے اسے بھى معمولى سمجھتاہے اور جب تك اسے توبہ وندامت كى توفیق نہ ملے اپنے حال پر جارى وسارى رہتاہے۔ (ابن عاشور: ۲۶؍۲۳۱)\nہمیں فاسق كى خبر كى تحقیق كا حكم كیوں دیاگیاہے؟\nوَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ\n(لو يطيعكم في كثير من الأمر لعنتم) یعنى تم شقى وبدبخت ہوجاتے، “العنت” كے معنى مشكل ومشقت كےہیں، الله تعالىٰ نے (لو يطيعكم) كہا (لَوْاَطَاعَكُمْ) نہیں كہا، یہ بتانے كیلئے كہ وه لوگ چاہتےتھے كہ آپ صلی اللہ علیہ وسلم ان كى اطاعت جارى رکھے جو کہ حق كےخلاف ہے۔بلکہ واجب یہ ہے کہ وہی لوگ آپ صلی اللہ علیہ وسلم كى اطاعت کریں نہ كہ آپ صلی اللہ علیہ وسلم ان كى اطاعت کریں ، اس لئے كہ رسول اللہ صلی اللہ علیہ وسلم كى رائے دوسروں كى رائے سے زیاده بہتر وافضل ہے۔اگر آپ صلی اللہ علیہ وسلم لوگوں كى اطاعت كریں گے تو لوگ ہلاك ہوجائیں گے، اس لئے ضرورى ہے كہ آپ صلی اللہ علیہ وسلم كى تابعدارى كى جائےاور آپ كى طرف رجوع كیا جائے، اس آیت میں انہی باتوں كى طرف اشاره ہے (ولكن الله حبب إليكم الإيمان) (ابن جزى: ۲؍۲۷۵)\nآیت سے سمجھ میں آتاہے کہ وہ وضعى قوانین جو اسلامى شریعت كےمخالف ہیں، ان میں مشقت وہلاكت ہے۔ اسكى وضاحت كیجئے.\nوَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ ٧\n(رشد)كامعنى طریق حق پر سختى سے جم جاناہے… ، رشد وہدایت كو وہى پہنچے گا جو حق كو مانےگا یقیناً الله تعالىٰ ایسے شخص كى صحیح رہنمائى كرےگا اور ندامت کے منافی ان کی كوششوں كو كامیابى عطا كرےگا ،جو خیر وبھلائى كاقصد كرےگا اور كارِخیر میں محنت ومشقت كرےگا، الله تعالىٰ فرماتاہے: ﴿وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ﴾ ۔(البقاعى : ۷؍۲۲۹)\nرشد وہدایت كا عظیم مقام ہے ، بنده اس مقام تك كیسےپہونچےگا؟\nإِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ\nیعنی مسلمان آپس میں دینى بھائى بھائى ہیں نہ كہ نسب میں ، اسی وجہ سے کہاگیا ہے کہ دینى اخوت نسبى اخوت سے زیاده پائیدار ہے؛ كیونكہ نسبى اخوت اختلافِ دین كى بناپر منقطع ہوجاتى ہے جبكہ دینى اخوت اختلاف نسب سےمنقطع نہیں ہوتى۔(القرطبى: ۱۹؍۳۸۳)\nدینى ونسبى اخوت میں سب سے زیاده پائیدار كونسى اخوت ہے اور كیوں؟\nإِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ١٠\n(رحمت ) كا انتخاب ہوا ہے؛ كیونكہ تقوىٰ كا حكم مومنوں کے درمیان اخوت كى حقیقت كے اثبات كےبعد آیا ہے اور اسلامى بھائیوں كاباہمی برتاؤ رحمت وشفقت كى بنیاد پر ہوتاہے، اس لئے بدلہ بھی اس کے ہم جنس سے ہی ہوگا۔(ابن عاشور: ۲۶؍۲۴۵)\nآیت كریمہ میں(رحمت) كو كیوں اختیار كیا گیاہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ\nسلف افراط كى حد تك مسخرےپن سے بچتےتھے، عمرو بن شرحبیل كہتےہیں كہ میں كسى شخص كو بكرى سے دودھ پیتے دیكھ لوں اور اس پر ہنسوں تو مجھے ڈر ہے كہ كہیں میں بھى اسى طرح نہ ہوجاؤں ، اور عبد الله بن مسعود (رضی اللہ عنہ )كہتےہیں: ابتلاء وامتحان قول پر مبنى ہے، اگر میں كسى كتےكا مذاق اڑاؤں تو ڈر ہے كہ میں كہیں كتا نہ ہوجاؤں۔ (القرطبى: ۱۹؍۳۸۳)\nسلف قرآن پر كس طرح عمل كرتےتھے، اس آیت كى تفسیر كى روشنى میں وضاحت كیجئے.\nوَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ\nالله تعالىٰ فرماتاہے : اے مومنو! تم میں سے كوئى كسى دوسرے كى غیبت نہ كرے اور نہ ہى ایك دوسرے پر طعنہ زنى كرے، اور فرمایا: اپنے بھائى پر طعنہ زنى كرنے والا خود پر طعنہ زنى كرتا ہے، اس لئے كہ تمام مومن اپنے معاملہ كى تحسین وبھلائى اور خیر كى محبت میں ایك ہى شخص كى مانند ہیں جو ایك پر ضرورى ہے وہى دوسروں پر بھى ضرورى ہے ، لہذا حدیث میں آتاہے: (اَلْمُؤْمِنُونَ كَرَجُلٍ وَاحِدٍ اِنِ اشْتَكٰى رَأْسُهٗ تَدَاعٰى لَهٗ سَائِرُ الْجَسَدِ بِالْحُمَّى وَالسَّهَرِ) مسلمان بھائى آپس میں ایك بدن كى طرح ہیں، اس كے كسى عضو كو مرض لاحق ہوتا ہے تو اس كے سارے اعضاء بخار وبےچینى سے چیخ پڑتےہیں۔ (الطبرى: ۲۲؍۲۹۸)\nآیت میں (أنفسكم) كى تعبیر كیوں لائى گئى ہى؟ اور كیا انسان خود پر عیب لگا سكتاہے؟\nwords\nبِنَبَإٍاطلاع / خبر / علم.\nفَتَبَيَّنُواپس اس خبر كي تصديق كر ليں.\nلَعَنِتُّمضرور تم مشقت ميں پڑ جاتے.\nبَغَتاس نے سركشي كي.\nتَفِيءَوه الله اور اس كے رسول كے حكم كي طرف رجوع كرے.\nوَلاَ تَلمِزُواتم ايك دوسرے پر طعنه زني نه كرو.\nوَلاَ تَنَابَزُوا بِالأَلقَابِتم ميں سے كوئي ايك دوسرے كو برے نام سے نه پكارے."],[517,"§الحجرات\ndeeds\nایسے شخص كو یاد كیجئے جس كے تعلق سے آپ بدگمانى میں مبتلا تھے اور اسكے لئے عذر تلاش كیجئے.\nجس كى غیبت كى ہے اسے یاد کیجئے اور اسكے حق میں بخشش طلب كیجئے اور دعائیں كیجئے.\nاپنے مال كےذریعہ الله كےراستے میں جہاد كیجئے یعنى اپنے مال كا كچھ حصہ کسی بھی خیر كے كاموں میں خرچ کیجئے.\nguid\nانواع واقسام كے كنبے وقبیلے آپس میں تعارف ومحبت كے لئے وجود میں لائے گئے ہیں نہ كہ تفرقہ، اختلاف اور نعره بازى كیلئے.\nیہ خیال كرنا كہ برترى كا معیار وبنیاد تقوىٰ كےعلاوه پر ہے، نادانى وغفلت ہے.\nكار خیر كى توفیق پر الله كا شكر بجا لائیے اوراحسان مت جتلائیے كیونكہ الله تعالىٰ اس سےمحروم بھى كرسكتاہے.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَ لَا تَجَسَّسُواْ\nاس کی وجہ یہ ہے کہ ابتداء میں اس کے دل میں تہمت کا خیال آتا ہے وہ اس خبر کے لئے جاسوسی کرتا ہے اور بحث و تمحیص کرتا ہے وہ توجہ سے دیکھتا ہے اور توجہ سے سنتا ہے تاکہ وہ امر ثابت ہوجائے جو اس تہمت سے واقع ہوا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے اس سے منع کیا۔ آپ چاہیں تو یہ کہہ سکتے ہیں کہ بدگمانیوں میں تمییز کرنے کا ضابطہ یہ ہوگا کہ جس کی آپ صحیح علامت اور ظاہری سبب نہ پائیں تو وہ حرام ہے اور اس سے اجتناب ضروری ہے۔ (القرطبى: ۱۹؍۳۹۶)\nوه بدگمانى جو شرعا حرام ہے، وه كیا ہے؟\nوَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ\nابو قلابہ الرقاشى كہتےہیں كہ میں نے ابو عاصم كو كہتےہوئے سنا: غیبت كى شناعت معلوم ہوجانے كےبعد میں نے كسى كى غیبت نہیں كى اور میمون نہ خود كسى كى غیبت كرتے اور نہ ہى اپنى مجلس میں دوسروں كوغیبت كرنے دیتے تھے، غیبت كرنے والے كو منع كرتے تھے وہ رک جاتا تو ٹھیك ورنہ وه وہاں سے نكل لیتےتھے۔(القرطبى: ۱۹؍۴۰۴)\nغیبت سے ڈرانے والے سلف سے منقول دو اثر بیان كیجئے.\nوَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ\nالله تعالىٰ نے غیبت كى تشبیہ مردار كو كھانے سے دى ہے كیونكہ مرده اپنے گوشت کے کھائے جانے سے لاعلم ہوتا ہے اسى طرح باحیات شخص بھى اپنے بارےمیں ہونے الى غیبت سے بےخبر ہوتاہے، حضرت ابن عباس(رضی اللہ عنہ) فرماتےہیں : الله تعالىٰ نے غیبت كى جو مثال پیش كى ہے اس كى توجیہ یہ ہے كہ جس طرح میت كا گوشت كھانا حرام اور گنده ہے اسى طرح غیبت حرام اور لوگوں كے نزدیك قبیح عمل ہے ۔ قتاده فرماتےہیں: جس طرح تم میں سے کوئی ایک اپنے مرده بھائى کا گوشت كو كھانے سے باز آتاہے، اسى طرح ضرورى ہےكہ اپنے باحیات بھائى كى غیبت سے بھى باز آجائے۔(القرطبى: ۱۹؍۴۰۳)\nغیبت كو مرده انسان كے گوشت كھانے سے مشابہت دى گئى ہے ، اسكى توجیہ كیا ہے؟\nوَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ\nحضرت عمر بن خطاب (رضی اللہ عنہ) فرماتےہیں: لوگوں كى برائى سے یعنى غیبت كرنے سے بچو، كیونكہ وه ایك بیمارى ہے اور الله كے ذكر واذكار كو لازم پكڑو كیونكہ اس میں شفا ہے اور حضرت على (رضی اللہ عنہ) نے ایك شخص كودوسرے شخص کی غیبت كرتےہوئے سنا تو فرمایا: غیبت سے بچو؛ كیونكہ یہ تو لوگوں کے کتوں کا سالن ہے۔ اور عمروبن عبید كو خبردى گئى كہ فلاں نے آپ كى غیبت كى ہے حتى كہ ہمیں آپ پر رحم آنے لگا تو آپ نے فرمایا: اسى پر رحم كھاؤ، اوركسى نے حسن بصرى (رحمہ اللہ)سے شكایت كى كہ مجھے خبر ملى ہے كہ آپ میرى غیبت کرتے ہیں تو آپ نے فرمایا: تیرا مقام ومرتبہ میرےپاس اتنا بڑا نہیں ہے كہ میں اپنی نیكیوں کا فیصلہ تیرے حق میں کردوں۔(القرطبى: ۱۹؍۴۰۴)\nغیبت كى مذمت میں بعض سلف كےاقوال پیش كیجئے.\nوَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا\nالله تعالىٰ نے حرمتِ غیبت كى وجہ اسلامى اخوت كو قرار دیا ہے، لہذا مومن كى ایمانی حالت وكیفیت كےا عتبار سے غیبت شدت اختیار کرتی ہے ، مسلمان اپنے ایمان میں جس قدر مضبوط وقوى ہوگا ، اس كى غیبت بھى اسى قدر خطرناك اور سخت ہوگى۔(ابن تیمیہ: ۶؍۶۲)\nكیا مومن كى غیبت ایك ہى درجہ کی ہے؟ اسے آیت کی روشنی میں واضح کیجئے.\nوَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ\nالله تعالىٰ نے واضح كردیا ہے كہ كنبے وقبیلے كى یہ تقسیم آپس میں تعارف اور تمییز كیلئےہے نہ كہ ایك دوسرے پرفخر اور برترى كےاظہار كےلئے، لہٰذا پتہ چلا كہ برترى كا معیار نسل ونسب كےعلاوه كوئى اور چیز ہے اور وه تقوىٰ وخشیتِ الٰہى ہے جس كى وضاحت اس آیت میں ہے: (إن أكرمكم عند الله أتقاكم) اس سے واضح ہوا كہ برترى وفضیلت كى بنیاد تقوى ہے نہ کہ كنبے قبیلے كى طرف نسبت ۔(الشنقیطى: ۷؍۴۱۷)\nآیت نے واضح لفظوں میں افضلیت وبرترى كا معیار بتایا ہے ، اس كو بیان كیجئے.\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ\nحقیقى مومن وه ہے جو ایمان كےساتھ ساتھ راهِ خدا میں جہاد بھى كرتاہے كیونكہ كافروں سے جہاد كرنا ایمان كامل كى علامت ہے، اور جو غیروں سے اسلام اور شریعت كى برترى اورنشرواشاعت كى خاطر جہاد كرےگا وه اپنے نفس سے بدرجۂ اولى جہاد كرےگا۔(السعدى: ۸۰۲)\nحقیقى مومن كیلئے الله نے اس آیت میں ایمان وجہاد كو كیوں جمع كردیا ہے؟\nwords\nكَثِيرًا مِنَ الظَّنِّبهت سارے گمان ۔ مؤمنين سے متعلق بدگماني.\nوَلاَ تَجَسَّسُواپس تم مسلمانوں كے عيب نه تلاش كرو.\nوَلاَ يَغتَبكوئي غيبت نه كرے۔ اپنے بھائي كي عدم موجودگي مكروه بات نه كهے.\nوَقَبَائِلَقبيله / جماعت.\nالأَعرَابُبدو / ديهاتي.\nلاَ يَلِتكُم مِن أَعمَالِكُمتمهارے اعمال كا ثواب كم نه كرے گا."],[518,"§ق\ndeeds\nكسى غافل مسلمان كو زبانى نصیحت كیجئے یا نصیحت كا ایك خط روانہ كیجئے.\nبہتے خون یا سمندر میں غور كیجئے اورآپ کے دل میں کھٹکنے والی قدرت الٰہى کی نشانیوں میں سے د و نشانیوں كو نوٹ كیجئے.\nایك بے جان درخت كا تصور كیجئے اور اس كى عمر كے تمام مراحل كو یاد كیجئے اور پھر اس كا موازنہ اپنى عمر كےان تمام مراحل سے كیجئے جن سے آپ گزرنے والے ہیں .\nguid\nقرآن مجید كا مقام ومرتبہ اور اس پر عمل كرنے والوں كى قدر ومنزلت.\nتوحیدِ الوہیت پر توحیدِ ربوبیت كے ذریعہ استدلال.\nعدم سے تخلیق كى قدرت ركھنے والا موت كے بعد زنده كرنے پر بدرجۂ اولىٰ قادر ہے.\nrefl\nسورة قٓۚ\nیہ سورت ایمان کے اہم بنیادى نقاط پر مشتمل ہے ، یہى وجہ ہے كہ آپ صلی اللہ علیہ وسلم بڑے مجمع میں اس كى تلاوت كرتےتھے، خطبۂ جمعہ وعیدین میں اس كو پڑھتےتھے، اور چونكہ بكثرت آپ اس كى تلاوت كے عادى تھے اس لئے نماز فجر میں بھى اسى كو پڑھتے تھے۔(ابن تیمیہ: ۶؍۸۳)\nلوگوں كے بھرے مجمع میں آپ صلی اللہ علیہ وسلم اس سورت كى بكثرت تلاوت كیوں كرتےتھے؟\nقٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ ١\nلفظ(مجید) قرآن كى ایك عظیم ووسیع صفت ہے اور وه اس صفت كا بجا طور پر حق دار ہے، اس صفت كا واجبى تقاضہ یہ ہے كہ اس كى مكمل اتباع كى جائے اور اسكے احكام كى فى الفور اطاعت كى جائے، اور اس احسان پر الله كا شكر بجالایا جائے۔(السعدى: ۸۰۳)\nقرآن کو صفتِ (مجید)سے متصف کیا گیا تو اس صفت كا واجبى تقاضہ كیا ہے؟\nبَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ ٥\nآیت كى تفسیر میں قتاده فرماتےہیں: جو حق كو ترک كرے گا وه اپنے معاملہ میں اضطراب اور اپنے دین میں التباس واشتباه كا شكار ہوجائےگا۔ اور حسن بصرى (رحمہ اللہ) فرماتے ہیں كہ جب بھى كسى قوم نے حق كا دامن چھوڑا اس كے مسائل الجھتے اور پیچیده ہوتے چلےگئے۔(القرطبى: ۲۱؍۳۱۶)\nبعض لوگوں پر ان كے معاملات الجھنے كى وجہ كیا ہے؟\nأَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٖ ٦\nیعنی غور وفکر کی یہ نظر کسی مشقت اور سامانِ سفر باندھنے کی محتاج نہیں، بلکہ بہت آسان ہے وہ دیکھیں (كَيفَ بَنَينَاهَا)کہ ہم نے اسے کیسے ایک گنبد بنایا جو اپنے کناروں پر برابر اور مضبوط بنیاد رکھتا ہے، جسے ان ستاروں سے آراستہ کیا گیا ہے جو پیچھے ہٹ جاتے ہیں اور چلتے چلتے غائب ہوجاتے ہیں، جو ایک افق سے دوسرے افق تک اپنے حسن و ملاحت میں انتہا کو پہنچا ہواہے، تو اس میں کوئی سوراخ دیکھے گا نہ شگاف اور نہ تجھے اس میں کوئی خلل نظرآئے گا ۔اللہ تعالیٰ نے اسے اہلِ زمین کے لئے چھت بنایا ہے اور اس کے اندر ان کے لئے ضروری مصالح ودیعت کئے ہیں۔(السعدى: ۸۰۴)\nسب جانتےہیں كہ آسمان ان كے اوپر ہے پھر بھى الله نے آسمان كى صفت فوقیت كا كیوں ذكر كیا ہے؟\nتَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ ٨\nزمین كے جو احوال بتائےگئےہیں ان میں ہر ایك كیلئے بصیرت ودانائى اور عبرت ونصیحت ہے لیكن الله كى طرف رجوع كرنے والے بندوں كیلئے عبرت وبصیرت كو مختص كردیا گیا ہے كیونكہ عبد منیب ہى ان سے حقیقى فائده اٹھاتاہے گویا ان افعال كا مقصود وہى بنده ہے ، یہ جہاں مومن بندوں كیلئے شرف كى بات ہے وہیں یہ بھی اشاره ہے كہ كافر عبرت وبصیرت میں اہمال وسستی سے كام لےرہےہیں۔(ابن عاشور: ۲۶؍۲۱۹)\nعبد منیب كےساتھ عبرت وبصیرت كو كیوں خاص كردیا گیا ہے؟\nوَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتٖ وَحَبَّ ٱلۡحَصِيدِ ٩ وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ ١٠ رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ ١١\nمذكوره آیتوں میں تنبیہ واشاره ہے كہ بندوں كیلئے بابركت پانى اور اس سے حاصل ہونے والے رزق وغیره سے عبرت وموعظت اور نصیحت وبصیرت حاصل كرنا بحیثیت رزق فائده ولذت حاصل كرنے سے زیاده اہم ہونا چاہئے۔(الألوسى: ۱۳؍۳۳۷)\nمومن بارش سے اہم فائده كیا اٹھاسكتاہے؟\nكَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ ١٢ وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ ١٣ وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ ١٤\nان آیتوں میں آپ صلی اللہ علیہ وسلم كیلئے تسلى ہے، گویا آپ سے كہاجارہاہے كہ كافروں كى تكذیب پر بہت زیاده حزین وغمگین نہ ہوں ، اس لئے كہ یہ معاملہ آپ سے پہلے آئے ہوئے پیغمبروں كے ساتھ ہوتا آرہاہے، ان کی قوموں نے اپنے اپنے رسولوں كو جھٹلایا اور بہت كم لوگوں نے ان كى تصدیق كى اور ان پر ایمان لائے ۔(الشوكانى: ۵؍۷۳)\nدعوت اور امر بالمعروف ونہى عن المنكر كا فریضہ انجام دینے والے اس آیت سے كیا فائده اٹھاسكتےہیں؟\nwords\nمَرِيجٍمضطرب / ملا هوا / جو كسي چيز پر ثابت نه رهے.\nفُرُوجٍشگاف ؛ چير.\nزَوجٍ بَهِيجٍحسن منظر كي ايك قسم / خوشنما جوڑا.\nوَحَبَّ الحَصِيدِكھيتي كے وه دانے جو كاٹے جاتے هيں.\nبَاسِقَاتٍلمبے / طويل.\nطَلعٌ نَضِيدٌته به ته خوشے/ پھل.\nالرَّسِّرس / كنواں.\nأَفَعَيِينَاكيا هماري قدرت كمزور پڑ گئي؟"],[519,"§ق\ndeeds\nیہ دعا پڑھئے: “اَللّٰهُمَّ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَشَرِّ الشَّيْطٰنِ وَشِرْكِهٖ” اے الله ! میں اپنے نفس كے شر اور شیطان كےشر اور اسكى شراكت سے تیری پناه میں آتا ہوں.\n“سُبْحٰنَ اللّٰهِ وَبِحَمْدِهٖ سُبْحٰنَ اللّٰهِ الْعَظِيْمِ” كہئے تاكہ آپ اسے اپنے اعمال نامہ میں پائیں.\nقبرستان كى زیارت كیجئےاور غفلت سے الله كى پناه طلب كیجئے.\nguid\nفرشتوں کا بندوں كے اعمال كو نوٹ كرنا بندوں کے گوشۂ مراقبت كو پروان چڑھاتاہے.\nالله سے غافل نہ رہو.\nبخالت جہنم كا ایك راستہ ہے.\nrefl\nوَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ ١٦\nالله تعالىٰ خبر دےرہاہے كہ وہ رگِ جاں سے بھى زیاده قریب ہے جو انسان كا قریب ترین حصہ ہے اس سے مراد وہ رگ ہے جس نے سینے کے گڑھے کا احاطہ کررکھا ہے،اور یہ بات انسان كو دعوت دے رہى ہے كہ وه اپنے خالق كے مراقبہ میں رہے جو اس كے ضمیر وباطن سے آگاه ہے، اور اسكے تمام امور میں اس سے قریب ہےاس لئے انسان کو چاہئے کہ ایسے کام کے ارتکاب سے حیا کرے جس کام سے اللہ نے منع کیا ہے اس لئے کہ اللہ اس کو دیکھتا ہے، اور جس کام کا اللہ نے حکم دیا ہے اسے ترک نہ کرے ۔(السعدى: ۸۰۵)\nشہ رگ كے خاص تذكرےمیں كیا حكمت پوشیده ہے ؟ اور ہم اس سے كیا فائده اٹها سكتےہیں؟\nوَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ ١٦\nمطلب یہ ہے كہ جس نے انسان كو پیدا كیا اور جو اس كے دل میں پیدا ہونے والے خیالات سے بھى واقف ہے اور اس كے شہ رگ سے بھى زیاده قریب ہے، وه فرشتوں كےانسانى اعمال کو نوٹ كرنے کا محتاج نہیں ہے کیونکہ وہ ان سے آگاہ ہے، كوئى چیز اس سے مخفى نہیں ہے ،لیکن اسکے باوجود فرشتوں كو عمل نوٹ كرنے کا مكلف کیا یہ چند مقاصد كے حصول كیلئے ہے مثلا قیامت كے دن بندوں پر اتمام حجت قائم کرنا۔(الشنقیطى: ۷؍۲۲۶)\nالله تعالىٰ بندوں كے اعمال سے واقف ہے، كوئى چیز اس پر مخفى نہیں ہے، پھر بندوں كے اعمال نوٹ كرنے كے حكم میں كیا فائده ہے؟\nوَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ ١٩\n(جاءت ) ماضى كا صیغہ موت كے متحقق ہونے اور اس كے قرب پر دلالت كرنے كیلئے استعمال ہوا ہے۔(ابن جزى: ۲؍۳۶۵)\nماضى كى تعبیر میں بلیغ نكتہ ہے، وه كیا ہے؟\nيَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ ٣٠\nحضرت ابوہریره (رضی اللہ عنہ) سےروایت ہے كہ رسول الله صلی اللہ علیہ وسلم نے فرمایا: جنت وجہنم میں بحث و مناظرہ ہوا۔ جہنم نے كہا: مجھے تكبر وجبر كرنے والوں كا ٹھكانہ بنایا گیا ہے، اور جنت نے كہا: كیا ہوگیا ہے مجھے ، میرے اندر ضعیف ، كمزور اور بےحیثیت لوگ داخل ہوں گے، تو الله تعالىٰ نے جنت سےفرمایا: تو میرى رحمت ہے، تیرے ذریعے میں جس بنده پرچاہوں گا رحم كروں گا، اورجہنم سے فرمایا: تو میرا عذاب ہے، تیرے ذریعے میں اپنے بندوں میں سے جسكو چاہوں گا عذاب میں ڈالوں گا، اور تم میں سے ہر ایك كو بھرنا ہے، جہاں تك جہنم كى بات ہے تو وه نہیں بھرے گى یہاں تك كہ الله تعالىٰ اپنا قدم ركھ دے گا تووه كہےگى: بس بس اور بھر جائےگى، اور اس كے بعض حصے بعض كےساتھ سمٹ جائیں گے اور الله تعالىٰ كسى مخلوق پر ظلم نہیں كرےگا اور جہاں تك جنت بھرنے كى بات ہے تو الله تعالىٰ اسكے لئے نئى مخلوق پیدا كر ے گا ۔ (الألوسى: ۲۶؍۴۷۱)\nاہل جنت واہل دوزخ كےبعض واضح صفتوں كو بیان كیجئے.\nهَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ ٣٢\n(أواب) كا مطلب معصیتوں وگناہوں سے تائب ہوكر الله كى طرف بہت زیاده رجوع كرنے والا ، یعنى بنده گناه كرےگا اور پھر الله كى طرف پلٹ جائےگا۔ ضحاك وغیره نے اسكا یہی معنی بیان كیا ہے۔ اور حضرت ابن عباس وعطاء كےنزدیك (أواب) كا معنى : تسبیح بیان كرنے والا ہے جو آیت : ﴿يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَ﴾ [سبأ: ۱۰] “اے پہاڑو! اس (أواب)كےساتھ بہ رغبت تسبیح پڑھا كرو، اور پرندوں كو بھى (یہى حكم ہے)” سے ماخوذ ہے ۔ اور حكم بن عتیبہ كہتےہیں: (أواب) کا معنیٰ خلوت میں الله كو یادكرنے والا ، اور شعبى ومجاہد كےنزدیك (أواب) وه شخص ہے جو خلوت میں اپنے گناہوں كو یاد كرتاہے اور الله سے مغفرت طلب كرتاہے اور یہى حضرت ابن مسعود (رضی اللہ عنہ) كا قول ہے ۔ اور عبید بن عمیر اس كى تفسیر میں كہتےہیں : (أواب)وه ہے جو ہر مجلس میں الله سے مغفرت طلب كرتاہے، اور ان ہی سے یہ قول بھى منقول ہے کہ ہم سے بیان کیا جاتاتھا کہ (أواب حفيظ )سے مراد وہ شخص ہے کہ جب اپنی مجلس سے اٹھتاہے تو كہتاہے: “سُبْحٰنَ اللّٰهِ وَبِحَمْدِهٖ اَللّٰهُمَّ إِنِّىْ اَسْتَغْفِرُكَ مِمَّا أَصَبْتُ فِىُ مَجْلِسِىْ هٰذَا” الله تو پاك ہے اور تیرا شكر بجالاتاہوں ، اے الله! مجھ سے اس مجلس میں جوگناه سرزد ہوا ہے اس سےتیرى بخشش طلب كرتاہوں ۔ (البغوى: ۱۹؍۴۵۴)\n(أواب) كى تین صفتیں بیان كیجئے.\nمَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ ٣٣\nاللہ تعالیٰ کے قول (من خشي الرحمن بالغيب)میں لفظ جلالہ “الله” پر (الرحمن) كو ترجیح دی گئی ہے یہ بتانے كیلئے كہ یہ متقى الله سے خوف كھاتاہے اس یقین كےساتھ كہ وه رحمٰن (بہت رحم كرنے والا) ہے نیز اس میں كنایۃً مشركوں پر رد بھى ہے جو (رحمت) نام كا انكار كرتےتھے،﴿وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ﴾ [الفرقان: ۶۰] ان سے جب بھى كہا جاتاہے كہ رحمٰن كو سجده كرو تو جواب دیتےہیں رحمن کیا ہے؟ (ابن عاشور: ۲۶؍۳۲۰)\nآیت میں الله كے (رحمٰن )نام كو ترجیح دى گئى ہے ، اس كا فائده كیا ہے؟\nوَجَآءَ بِقَلۡبٖ مُّنِيبٍ ٣٣\nیعنی لوگوں كى نگاہوں سے دور ره كر خلوت میں الله سے ڈرنا یہى حقیقى خشیت ہے لیکن جہاں تک لوگوں كى نظروں كےسامنے اور ان كى موجودگى میں خدا کے خوف کا تعلق ہے تو یہ ریاء و شہرت ہے جو خشیت سے عاری ہے، بلكہ نافع ومفید خشیت یہ ہے كہ خلوت وجلوت دونوں میں الله كا خوف كھایا جائے۔(السعدى: ۸۰۶- ۸۰۷)\nخشیت كو غیب كےساتھ بطور خاص كیوں ذكر كیا گیا ہے؟\nwords\nحَبلِ الوَرِيدِگردن كي ايك رگ جو دل سے متصل هوتي هے.\nرَقِيبٌ عَتِيدٌتيار نگهبان / ايك فرشته جو هر قول و فعل كو لكھتا هے.\nتَحِيدُتم بھاگو گے.\nقَرِينُهُاس كا ساتھي۔ وه فرشته جو اس پر گواهي لكھتا هے.\nمُعتَدٍظالم / حد سے تجاوز كرنے والا.\nمُرِيبٍالله كے وعده و وعيد ميں شك كرنے والا.\nمَا أَطغَيتُهُميں نے اس كو گمراه نهيں كيا.\nوَأُزلِفَتِاور قريب كي گئي.\nمُنِيبٍتائب / اطاعت پر لگا هوا."],[520,"§ق ، الذاريات\ndeeds\nپانچوں فرض نمازوں كو جماعت كےساتھ مسجد میں ادا كیجئے.\nنماز فجر كےبعد اپنى جگہ بیٹھے رہئے اور طلوع آفتاب تك تسبیح پڑھتےرہئے.\nمغرب كى اذان سے كچھ وقت پہلے مسجد جائیے اور وہاں بیٹھ كر غروب آفتاب تك تسبیح میں لگے رہئے.\nguid\nعقل مند وه ہے جو دوسروں سے عبرت پكڑ ے.\nدل نصیحت حاصل كرےاس لئے اسے دلوں كے امراض وآفات سے بچائیے اور اسكے حریص رہئے.\nصبر اور تسبیح بیان كرنا دونوں قرین (متلازم) ہیں، اس لئے دونوں خوبیوں سے متصف ہونے كى حرص ركھئے.\nrefl\nإِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ ٣٧\nجس نے آیات الٰہى پر دھیان دیا اور ان سے رہنمائى حاصل كرنے كیلئے انہیں بغور سنا اور اس کا دل حاضر رہا تو ایسے شخص كیلئے یہ آیتیں عبرت ونصیحت اور شفا وہدایت ہیں اور جس نے آیتوں كو توجہ سے نہیں سنا بلكہ اعراض وادبار سے كام لیا تو یہ آیتیں اسے كچھ بھى فائده نہیں پہنچائیں گى، كیونكہ وه شخص جذبۂ قبول ہى نہیں ركھتا، اور نہ ہى مذكوره صفتوں سے متصف شخص بتقاضۂ حكمتِ الٰہى ہدایت پاسكتاہے۔(السعدى: ۸۰۷)\nجو قرآن كو بحضورِ قلب نہیں سنتا اور نہ ہى دھیان دیتا اور متنبہ ہوتا ہے تو كیا وه قرآن سے فائده اٹھا سكتاہے؟\nإِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ ٣٧\n(واو) كى جگہ (اَوْ)لانے كا راز یہ ہے كہ آیتوں سے فائده اٹھانے والے دو قسم كےلوگ ہیں: ۱۔ ذہین وسمجھ بوجھ ركھنے والے لوگ جو معمولى تنبیہ پر اپنى ہدایت كى فكر كرنےوالے ہوتےہیں، وه دل ودماغ كو متفرق ومختلف جگہوں سے جمع وحاضر ركھنے كے محتاج نہیں ہوتے ، بلكہ سمجھدار وبیدار مغز ہوتےہیں، ہدایت كو قبول كرنےوالے ہوتے ہیں نہ كہ اعراض كرنے والے ، وه صرف ان تك ہدایت پہنچنے كےمحتاج ہوتےہیں كیونكہ وه پورى طرح تیار ومستعد ہوتےہیں۔ ۲۔ دوسرى قسم كےلوگ وه ہیں جن كےپاس پہلی قسم کے لوگوں كى طرح استعداد دو صلاحیت نہیں ہوتى ہے، ان كےپاس جب آیتوں اور ہدایتوں كا تذكره ہوتاہے تو وه بغور سنتے اور دھیان دیتےہیں اور قلب وفكر كو جمع كرتےہیں اور اپنى نظر وطریقۂ استدلال سے ان كى صحت وحسن كو جاننے كى سعى كرتےہیں۔(ابن القیم: ۳؍۱۶)\nآیت میں (واو) نہ لاكر (اَوْ)لایا گیا ہے اس میں كیا حكمت ہے؟\nفَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ٣٩\nیہاں صبر كے معاون امور كا حكم دیا گیا ہے یعنى طلوعِ آفتاب وغروبِ آفتاب سے قبل ، اور راتوں میں اور نمازوں كےبعد الله كى تسبیح وتحمید بیان كرنے سے صبرکی مدد ملتى ہے۔(ابن القیم: ۳؍۲۶)\nصبر كے معاون امور كیا ہیں؟\nفَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ٣٩ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ ٤٠\n(فاصبر على ما يقولون) اپنى مذمت اور رسالت كى تكذیب پر صبر كیجئے ، اور ان سے صرف نظر كرتےہوئے اپنے رب كى بندگى واطاعت میں لگےرہئے، اور صبح وشام اور راتوں میں اور نمازوں كےبعد اپنےرب كى تسبیح بیان كیجئے كیونكہ الله كےذ كر واذكار سے دل كو تسلى اور انسیت ملتى ہے اور صبر كرنا آسان ہوجاتاہے۔(السعدى: ۸۰۷)\nصبر كےبعد تسبیح كے حكم میں كیا حكمت ہے؟\nوَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ٣٩\nرازى كہتےہیں كہ كلمات كا ثواب حكمت ومعرفت كى باغوں سے نكلنے والى قوتوں پر موقوف ہے ، اور ضرورى ہے كہ دل كى آنكھ زبان كى طرح چلے اور حقائق ومعانى كا ادراك كرے ، یعنى تسبیح كا مقصود وہم وخیال اور حواس میں متصور ومترسم ہر چیز سے الله كى تنزیہ وپاكى بیان كرناہے۔ اور الحمد لله كہنا الله كے احسان اور اس كى تخلیقات كا پتہ دیتاہے اور یہ بھى بتاتا ہے كہ وہى ساری نعمتوں كا اكیلا مالك ہے۔(البقاعى: ۱۸؍۴۳۹)\nتسبیح كا مقصود كیا ہے؟\nوَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ\nیعنی آپ اس بات كے مكلف نہیں ہیں كہ آپ انہیں ہدایت قبول كرنے اور ایمان لانےپر مجبور كریں بلكہ آپ كا كام صرف دعوت وتبلیغ ہے۔(ابن كثیر: ۷؍۴۱۲)\nداعى كا عمل تحدید كےساتھ بیان كریں.\nوَٱلذَّٰرِيَٰتِ ذَرۡوٗا ١ فَٱلۡحَٰمِلَٰتِ وِقۡرٗا ٢ فَٱلۡجَٰرِيَٰتِ يُسۡرٗا ٣ فَٱلۡمُقَسِّمَٰتِ أَمۡرًا ٤ إِنَّمَا تُوعَدُونَ لَصَادِقٞ ٥ وَإِنَّ ٱلدِّينَ لَوَٰقِعٞ ٦\nالله تعالىٰ نے آیت میں مذكوره امور كى خصوصى قسم كھائى ہے كیونكہ یہ چیزیں انوكھى اور عادت كے برخلاف ہیں، اور جو ذات ان چیزوں پر قدرت ركھتى ہے وہى ذات وقت مقرره پر انسانوں كو دوباره زنده بھى كرسكتى ہے۔(الشوكانى : ۵؍۸۳)\nان امور كےساتھ بالخصوص كیوں قسم كھائى گئى ہے؟\nwords\nبَطشًاقوت اور غلبه / پكڑ.\nفَنَقَّبُواپس وه كريدنے لگے/ گھومنے لگے.\nمَحِيصٍجائے فرار.\nلُغُوبٍتھكاوٹ / تنگي.\nسِرَاعًاتيزي سے باهر نكلے.\nوَالذَّارِيَاتِهواؤں كي ايك قسم / جس ميں مٹي بھي ساتھ هوتي هے.\nفَالحَامِلاَتِ وِقرًابوجھ اٹھانے والي۔پاني سے بوجھل بادل.\nفَالجَارِيَاتِ يُسرًا(سمندر ميں) آساني سے چلتي كشتياں."],[521,"§الذاريات\ndeeds\nوقتِ سحر بیدار ہونے كیلئے تنبیہ(الارم) سیٹ كرلیجئے، اور بیدار ہوكر الله سے اپنے گناہوں كى بخشش طلب كیجئے.\nاپنى آمدنى كا ایك حصہ –معمولى ہى سہى- سائل ومسكین كو دینے كیلئے متعین كرلیجئے.\nاپنے گھر پر كسى دوست كو بلائیے اور اسكى تكریم كیجئے.\nguid\nنیك لوگوں كى حالاتِ زندگى كو یاد كرنے سے نیك بننے میں مدد ملتى ہے.\nیقین مانئے ، آپ کے رزق كى ذمہ دارى الله نے اپنے ذمے لے لى ہے.\nابراہیم (علیہ السلام) كے عظیم واقعات میں عبرت كى بڑى بڑى باتیں ہیں.\nrefl\nإِنَّكُمۡ لَفِي قَوۡلٖ مُّخۡتَلِفٖ ٨ يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ ٩\nقول مختلف (اختلافى بات) سے مرادقرآن کریم اور نبى صلی اللہ علیہ وسلم كےبارےمیں كافروں كى طرح طرح كى باتیں ہیں جن كى بنیاد اٹكلوں اوراندازوں پر ہے؛ كیوں کہ انہوں نے جب حق كو جھٹلایا تو ان كے آراء ومذاہب اور طور طریقےبدل گئے جبكہ حق ایك اور سیدھا راستہ ہے، تو جب بھى كوئى حق كو جھٹلائےگا تو وه مختلف طریقوں اور مذہبوں كا شكار ہوجائے گا، الله نے فرمایا:﴿بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ﴾ [ق: ۵] بلكہ انہوں نے سچى بات كو جھوٹ كہا ہے جبكہ وه ان كےپاس پہونچ چكى ہے پس وه ایك الجھاؤ میں پڑگئے ہیں۔ (اَمْرٍ مَّرِيْجٍ) سے مراد اضطراب اور اختلاط والتباس ہے۔(ابن القیم: ۳؍۳۲- ۳۳)\nالتزام واتباعِ وحی اتحاد واتفاق كا اہم سبب ہے، آیت كى روشنى میں اس كى وضاحت كیجئے.\nإِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ ١٥\nماہرینِ اصول فقہ سے یہ بات مخفی نہیں ہے کہ اصولیوں کے نزدیک اس آیت میں ایک مشہور قاعدہ ہے اور وہ یہ ہے کہ دلالت ِایماء وتنبیہ كےذریعے یہ جان لینا کہ جنت اور اسكى نعمتوں كو پانے كاسبب تقوىٰ وخشیت الٰہى ہے، اور راجح وصحیح بات یہ ہے كہ شرعى سبب ہی شرعى علت ہے ۔(الشنقیطى: ۷؍۴۳۹)\nاللہ تعالیٰ کے متقیوں کے بارے میں بتلانا اور خبر دینا ان کے دخول جنت کا سبب ہے اس كى وضاحت كیجئے.\nءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ ١٦\nآیت (آخذين ما آتاهم ربهم) کا ایک معنیٰ یہ ہے کہ اہل جنت کا آقا انہیں تمام نعمتوں اور آرزؤوں سے نوازے گا، اور وہ اپنے آقا سے راضی ہوکر یہ نعمتیں قبول کریں گے جن سے ان کی نگاہیں ٹھنڈی ہونگیں، ان کے نفوس خوش ہونگے، وہ ان کو نہ بدلنا چاہیں گے اور نہ ان سے منتقل ہونے کی خواہش کریں گے۔ اس میں ایک دوسرے معنیٰ کا احتمال ہے کہ یہ دنیا کے متقی لوگوں کا وصف بیان ہوا ہے یعنی اللہ تعالیٰ دنیا کے اندر جو اوامر و نواہی کو عطاکرتا ہے وہ نہایت خوش دلی اور انشراح صدر کے ساتھ قبول کرتے ہیں۔(السعدى: ۸۰۸)\nدنیا كےمتقى وپرہیزگار لوگوں كى علامت كیا ہے؟\nكَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ ١٧\nآیت كا مقصود یہ ہے كہ وه لوگ آرام وراحت كے اوقات میں عبادت كیا كرتےتھے ، اور دن كى مشقتوں پر بس تھوڑا سا آرام كرتےتھے۔ حسن بصرى(رحمہ اللہ) كہتےہیں: وہ قیام اللیل کے مشقتوں کو برداشت کرتے تھے اور رات كو بہت كم سویا كرتےتھے، اور عبد الله بن رواحہ(رضی اللہ عنہ) فرماتےہیں: تھوڑى دیر سوكر قیام اللیل كیلئے اٹھ جایا كرتے تھے۔(الألوسى: ۲۷؍۱۴)\nسكون وراحت اور سونے كے اوقات میں متقى لوگ كیا كرتے تھے كہ جنت اور اسكى نعمتوں كے مستحق ٹھہرے؟\nوَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ ١٨\nوقت سحر كى تخصیص اس لئے كى گئى ہے كیونكہ اس وقت انسانوں پر نیند كا غلبہ رہتاہے لہذا الله كے نزدیك اس وقت كى نماز واستغفار رات كے دوسرے حصہ كى نماز سے زیاده محبوب ہے۔ یہ لوگ چونكہ ہر رات بوقتِ سحر قیام اللیل كیا كرتےتھے اس لئے(اسحار) جمع كا صیغہ لایا گیا ہے۔(ابن عاشور: ۲۶؍۳۵۰)\nوقت سحر كى تخصیص كیوں كى گئى ہے؟\nوَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ ٢٢ فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ ٢٣\nبعض حكماء كہتےہیں: جس طرح ہر انسان اپنى زبان سے گفتگو كرتاہےاور دوسروں كى زبان سے بات كرنا اس كیلئے محال ہے، ویسے ہى ہر انسان اپنے حصہ كى روزى كھاتا ہے دوسروں كى روزى نہیں كھاسكتا۔(البغوى: ۱۹؍۲۳۱)\nرزق كو نطق وكلام سے تشبیہ دینے كى وجہ كیا ہے؟\nفَرَاغَ إِلَىٰٓ أَهۡلِهِۦ\nبلا بتائے چپكےسے نكل جانے كو (روغان) كہتےہیں، مہمان نوازى كےآداب میں سےہے كہ مہمان نواز مہمان كو احساس دلائے بغیر چپكے سے نكل جائے تاکہ اس پر شاق نہ گذرے اور اسے شرم محسوس نہ ہواور جب كھانےپینے كى چیزیں آجائے تب اسے احساس ہو۔اس كےبرخلاف بعض لوگ مہمان یا زائر كو سنا كر كہتےہیں كہ ٹھہرئیے كھانا وغیره لےكر آتاہوں ، یہ اور اس طرح کے دیگر الفاظ مہمانوں کے لئے باعثِ ندامت ہوتے ہیں۔(ابن القیم: ۳؍۴۵)\nانبیاء كرام كے (علیہم السلام) حسنِ اخلاق اور ان كے حسنِ تكریم ومہمان نوازى كى ایك علامت بتائیے.\nwords\nذَاتِ الحُبُكِراستوں والا؛ وه راستے جن پر كواكب سفر كرتے هيں.\nيُؤفَكُ عَنهُاس سے پھيرا جاتا هے.\nقُتِلَ الخَرَّاصُونَهلاك كئے گئے اٹكل لڑانے والے.\nيَهجَعُونَوه سوتے هيں.\nمُنكَرُونَپرديسي ؛ جن كي كوئي پهچان نه هو.\nفَرَاغَچپكے سے هٹ گيا.\nفَأَوجَسَ مِنهُمان كے متعلق اپنے دل ميں محسوس كيا."],[522,"§الذاريات\ndeeds\nجب ہوا چلے تو اللہ سے اس کی بھلائی کا سوال کیجئے اور اس کی برائی سے پناہ مانگئے.\nسومرتبہ پڑھئے: ‘‘اَللّٰهُمَّ اِنِّىْ اَسْتَغْفِرُكَ وَاَتُوْبُ اِلَيْكَ’’۔ ‘‘اے اللہ میں تجھ سے مغفرت چاہتا ہوں اور تجھ سے توبہ طلب کرتا ہوں’’.\nسوتے وقت یہ دعا پڑھیں: اَللّٰهُمَّ أَسْلَمْتُ نَفْسِىْ اِلَيْكَ، وَفَوَّضْتُ اَمْرِیْ اِلَيْكَ، وَوَجَّهْتُ وَجْهِىْ اِلَيْكَ، وَاَلْجَأْتُ ظَهْرِیْ اِلَيْكَ، رَهْبَةً وَرَغْبَةً اِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ اِلَّا اِلَيْكَ، اٰمَنْتُ بِکِتَابِكَ الَّذِیْ اَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِی اَرْسَلْتَ‘‘الٰہی میں نے اپنی جان تیرے سپرد کردی اور اپنامعاملہ تیرے حوالے کردیا، میرا چہرہ تیری جانب ہے ، اپنی پیٹھ میں نے تیری طرف ٹکادی ہے، خوف تیری ذات کا ہے شوق بھی تیری ذات کا ہے ، تیرے سوا کوئی راہ نجات ہے نہ پناہ گاہ، میں تیری نازل کردہ کتاب اور تیرے مبعوث کردہ نبی پر ایمان لایا’’.\nguid\nاپنی طاقت اور اپنے مال سے دھوکہ نہ کھائیے ورنہ ہدایت سے محروم ہو جائیں گے.\nگزشتہ امتوں کی بربادی کے جو کچھ اسباب تھے ان میں غورکریں.\nہرہر چیز میں اللہ کی طرف لوٹیں.\nrefl\n۞قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ٣١\nآپ نے مہمان نوازی کرنے کے بعد ان سے آمد کے بارےمیں پوچھا ۔کیونکہ ضیافت کا طریقہ یہ ہے کہ مہمان سے گھر آنے کی غرض تب تک نہیں پوچھنی چاہئے جب تک وہ جانے کی تیاری نہ کرنے لگے۔ اس کی وجہ یہ ہے کہ مہمان اپنی آمدکی بابت یہ نہ سوچ لے کہ میزبان اکتارہاہے اور میزبان اگر طاقت رکھتا ہو تو اس کی مدد بھی کر سکے ۔(ابن عاشور:۵؍۲۷)\nحضرت ابراہیم علیہ السلام نے ان کے بھیجے جانے کا سبب پوچھنے میں تاخیر کیوں فرمائی؟\nفَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتٖ مِّنَ ٱلۡمُسۡلِمِينَ ٣٦\nحضرت قتادہ (فما وجدنا فيها غير بيت من المسلمين) کی بابت فرماتے ہیں:اگر اس میں مزید لوگ ہوتے تو اللہ انہیں بھی نجات عطا فرماتا تاکہ انہیں اس بات کا یقین ہوجائے کہ اللہ کے یہاں ایمان کا اجر محفوظ رہتا ہے ضائع نہیں ہوتا۔(الطبری:۲۲؍۴۳۰)\nاہل ایمان کے گھروں میں ایمان کی قیمت واضح کیجئے ؟\nوَتَرَكۡنَا فِيهَآ ءَايَةٗ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ ٣٧\nاس واقعہ میں اس بات کی دلیل ہے کہ اللہ تعالیٰ کی نشانیاں اور عجائبات جنہیں اللہ نے اس جہاں میں وجود بخشا ہے اور ان کے آثار باقی رکھ چھوڑا ہے وہ اللہ کی ذات پر اوراس کے رسول کی صداقت پر دلالت کرتے ہیں ۔ مگر ان تمام چیزوں سے وہی فائدہ اٹھا سکتا ہے جو آخرت پر یقین رکھتا ہو اور اللہ کے عذاب سے خوف کھاتا ہو چنانچہ آخرت پر جس کا ایمان نہیں ہے زیادہ سے زیادہ یہی کہے گا کہ ‘‘یہ ایک قوم تھی جو گردش زمانہ کا شکار ہوگئی جس طرح دوسری قومیں اس کا شکار ہوئیں یہ وقت ہے کبھی اچھا بھی ہوتا ہے اور کبھی برا ’’ مگر جو آخرت پر ایمان رکھتا ہے اور اس سلسلے میں ڈرتا رہتا ہے تووہی آیات و مواعظ سے مستفید ہوتا ہے ۔(ابن قیم:۳؍۴۹–۵۰)\nقرآن پاک کے قصوں اور نصیحت کی باتوں (قصص و مواعظ) سے کون فائدہ اٹھاتا ہے ؟\nفَمَا ٱسۡتَطَٰعُواْ مِن قِيَامٖ وَمَا كَانُواْ مُنتَصِرِينَ ٤٥\nعذاب آجانے پر وہ کھڑے تک نہ ہو سکے (چہ جائیکہ وہ کہیں بھاگ سکتے ) اور نہ انہیں اٹھ پانے کی طاقت ہوئی ۔ قتادہ فرماتے ہیں : اس پٹخنی سے وہ اٹھ نہ سکے (وما كانوا منتصرين): یعنی وہ اللہ سے عذاب کا دفاع نہ کرسکے۔ قتادہ رحمہ اللہ فرماتے ہیں مفہوم آیت کایہ ہے کہ ان کے پاس ایسی کوئی قوت نہ تھی جس کی مدد سے اللہ کا عذاب روک سکتے ۔(البغوی:۴؍۲۳۳)\nاس آیت کے تناظر میں درج ذیل حدیث آپ کس طرح سمجھیں گے ؟ (إن الله ليملي للظالم حتى إذا أخذه لم يفلته) ترجمہ: ‘‘اللہ ظالم کو ڈھیل دیتا رہتاہے تاآنکہ اسے دبوچ لیتا ہے اور پھر نہیں چھوڑتا’’.\nوَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ ٤٩\nیہاں (تذكر) سے مرادحشر و نشر کے حوالے سے ذکر کی جانے والی تمام چیزوں سے نصیحت حاصل کرنا ہے ۔ کیونکہ جو ذات ان چیزوں کو وجود بخشنے پر قادر ہے وہ ذات روز قیامت مردوں کو زندہ کرنے پر بھی قدرت رکھتی ہے ۔ ((الألوسی:۲۷؍۲۷)\nدوبارہ زندہ کئے جانے پر اللہ کی قدرت کے سلسلے میں آیت کریمہ کس طرح رہنمائی عطا کرتی ہے؟\nفَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ٥٠\nعوام کا فرار جہالت سے علم کی طرف ہونا چاہئے عقیدہ اور عمل ہر دو اعتبار سے، سستی سے چستی کی طرف ہونا چاہئےاحتیاط اور دور اندیشی کے ساتھ، اور تنگی سے کشادگی کی طرف ہونا چاہئے بھروسہ اور امید کے ساتھ۔ (البقاعی:۱۸؍۴۴۷)\nاللہ کی طرف فرا ر کیسے ہوتا ہے؟\nفَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ ٥٠\nاللہ نے اپنی طرف‘‘رجوع ’’کرنے کو ‘‘فرار’’ یعنی اللہ کی طرف بھاگنے سے موسوم فرمایا ہے ۔ اس کی وجہ یہ ہے کہ غیر اللہ کی طرف رجوع کرنے میں مختلف طرح کے اندیشے اور پریشان کن چیزیں درپیش ہوتی ہیں لیکن اللہ کی طرف رجوع کرنے میں کامیابی ،خوش بختی امن و راحت اور محبت کے الگ الگ انداز موجود ہوتے ہیں تو بندہ اللہ کے قضاء و قدر سے اللہ ہی کے قضاء وقدر کی طرف بھاگتا ہے ۔ (السعدی:۸۱۲)\nرجوع الی اللہ کو اللہ نے فرارکانام کیوں دیا؟\nwords\nمُسَوَّمَةًنشان زده؛ كه يه رب كي طرف سے ظالموں كے ليے عذاب هيں.\nفَتَوَلَّى بِرُكنِهِان اپني طاقت پر ناز كرتے هوئے منه موڑا.\nفَنَبَذنَاهُم فِي اليَمِّهم نے ان كو سمندر ميں پھينك ديا.\nمُلِيمٌملامت كے كام كرنے والا.\nالعَقِيمَجس ميں كوئي بركت نه هو/ خير و بھلائي نه هو.\nمَا تَذَرُنه چھوڑتي تھي.\nكَالرَّمِيمِبوسيده چيز كي طرح.\nفَعَتَواانهوں نے تكبر كيا/ نافرماني كي."],[523,"§الذاريات ، الطور\ndeeds\nکسی مسلمان کو خوبصورت اور دلکش اسلوب میں نصیحت کیجئے.\nاللہ سے دعا کیجئے کہ اللہ آج آپ کے عمل میں مددفرمائے.\nاپنی کسی دنیاوی حاجت کا خیال کریں اور اللہ سے اس حاجت کا سوال کریں.\nguid\nاللہ نے ہمیں عبادت کے لئے پیدا فرمایا ہے توکیا ہم اس پر عمل پیرا ہیں ؟\nیادرکھیں روزیوں کامالک اللہ ہے اور وہ ہم سے بے نیاز ہے.\nکافروں کی ہلاکت کی بابت جلدی نہ کیجئے کیونکہ اللہ تعالیٰ غافل نہیں بس وہ ڈھیل دے رہا ہے.\nrefl\nفَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومٖ ٥٤ وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ ٥٥\nپھر جب ان سے اعراض کا حکم دیا تویہ بھی حکم دیا کہ یا ددہانی اور اچھے انداز میں نصیحت نہ چھوڑی جائے ۔(الشوکانی:۵؍۹۲)\nاعراض کا حکم دینے کے بعد نصیحت کا جو حکم ہے اس میں فقہ الدعوۃ کے حوالے سے ایک فائدہ موجود ہے اسے بیان کیجئے ؟\nوَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ ٥٥\nتذکیر(یعنی نصیحت کرنے) کاحکم دینے میں صرف ایک علت ‘‘تذکیر سے مومنوں کا فائدہ’’ ذکر فرمایا اس کی وجہ یہ ہے کہ اس بات کافائدہ ہونا یقینی ہے۔اور جس جگہ کافروں کے ساتھ بے توجہی کا اظہار کیا گیا اس جگہ مومنوں پر توجہ کااظہار کرنے کے لئے بھی ایک ہی علت کا ذکر کیا۔ اللہ نے فرمایا: ﴿ فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ * سَيَذَّكَّرُ مَن يَخۡشَىٰ * وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى﴾ (الاعلیٰ:۹۔۱۱) یعنی اگر نصیحت فائدہ دے تو آپ نصیحت کیجئے جو ڈرتا ہے وہ نصیحت حاصل کرے گا، اور بدبخت ہی اس سے کترائے گا۔(ابن عاشور:۲۷؍۲۴)\nتذکیر کاحکم دینے میں صرف مومنوں کے فائدہ حاصل کرنے والی علت کیوں بیان فرمایا؟\nوَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ٥٦\n(وما خلقت الجن والإنس إلا ليعبدون) میں جنات کا ذکر پہلے ہوا ہے تاکہ مشرکین کے یہاں اس انوکھی خبر کا اہتمام پیدا ہوجائے جوکہ جنات کی پوجا کرتے تھے تاکہ وہ لوگ جان لیں کہ جن اللہ کے بندے ہیں ۔(ابن عاشور:۲۷؍۲۸)\nآیت کریمہ میں انسانوں پر جناتوں کو کیوں مقدم کیا گیا ہے ؟\nإِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ ٥٨\nتمام عالم کو روزی پہنچانا اللہ کی قوت کاحصہ ہے ۔(السعدی: ۸۱۳)\nصفتِ رزاقیت کے بعد قوت کی صفت ذکر کی گئی ہے ۔دونوں میں کیا تعلق ہے ؟\nوَٱلطُّورِ ١ وَكِتَٰبٖ مَّسۡطُورٖ ٢ فِي رَقّٖ مَّنشُورٖ ٣ وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ ٤ وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ ٥ وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ ٦ إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ ٧ مَّا لَهُۥ مِن دَافِعٖ ٨\nایک رات حضرت عمر رضی اللہ عنہ گشت پر تھے۔ آپ کا گزر ایک مسلمان کے گھر سے ہوا اتفاق سے وہ کھڑا نماز پڑھ رہا تھا چنانچہ آپ رک گئے اور اس کی قرأت سننے لگے۔ اس نے پڑھا (وَ الطُّوْرِ) یہاں تک کہ (إن عذاب ربك لواقع * ما له من دافع) تک پہنچا ۔ آپ نے فرمایا: رب کعبہ کی قسم! قسم میں سچائی ہے پھر آپ اپنے گدھے سے اتر گئے اور ایک دیورا کے ساتھ ٹیک لگا لی اور ذرا دیر ٹھہرے رہے پھر اپنے گھر لوٹ گئے ایک مہینہ گھر ہی میں پڑے رہے کہ لوگ آپ کی عیادت کو آنے لگے اور کوئی نہیں جانتا کہ آپ رضی اللہ عنہ کو آخر بیماری کیا ہے ۔(ابن کثیر:۴؍۲۴۲)\nکیا سننے کے ذریعہ تدبر کرنا ممکن ہے ؟ بیان کیجئے.\nوَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ ٤\nانس بن مالک اپنی قوم کے ایک آدمی مالک بن صعصعہ سے روایت کرتے ہیں وہ کہتے ہیں کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا: میرے سامنے بیت معمور پیش کیا گیا تو میں نے جبریل سے پوچھایہ کیا ہے ؟ انہوں نے کہا یہ بیت معمور ہے اس میں ہر دن سترہزار فرشتے داخل ہوتے ہیں جب وہ اس سے نکل جاتے ہیں تو انہیں دوبارہ داخل ہونے کا موقع نہیں ملتا۔(الطبری:۲۲؍۴۵۵)\nبیت معمور کی شان بڑی بلند ہے ۔ اس بات کی دلیل کیا ہے؟\nفَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ١١ ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ ١٢\nجن اعمال اور علوم میں وہ مصروف تھے ان کا ذکر فرمایا ہے ۔ وہ اعمال و علوم دراصل ‘‘خوض’’پر مشتمل تھے جس کا معنی ہے قطعی باطل کلام ! اسی طرح ‘‘لعب’’ یعنی کھیل کود پر مشتمل تھے جو محض ایک برباد کوشش ہے ۔ گویا نہ نفع بخش علم تھا نہ صالح عمل، ان کے علوم محض باطل چیزوں میں لایعنی غوروفکر اور ان کے اعمال کھیل پر مبنی تھے۔(ابن القیم:۳؍۵۵)\nآیت میں مکذبین کی ذکر کردہ نمایاں صفات کیا ہیں ؟\nwords\nأَتَوَاصَوا بِهِكيا انهوں نے ايك دوسرے كو وصيت كي هے(كه وه اس كو جھٹلائيں گے).\nطَاغُونَكفر ميں حد سے تجاوز كرنے والے.\nذَنُوبًاان پر آنے والے عذاب كا ايك حصه.\nوَالطُّورِاس پهاڑ كي قسم هے جس پر موسي عليه السلام الله تعاليٰ سے هم كلام هوئے.\nفِي رَقٍّ مَنشُورٍپھيلے هوئے صحيفوں ميں.\nتَمُورُمتحرك هوگا/ اضطراب ميں آئے گا.\nيُدَعُّونَوه سختي اور شدت سے هٹائے جائيں گے."],[524,"§الطور\ndeeds\nکہئے : ‘‘اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ الْهُدٰی وَالتُّقٰى، وَالْعَفَافَ وَالْغِنٰى’’ (الٰہی میں تجھ سے ہدایت، تقوی ، پاک دامنی اور بے نیازی کا سوال کرتا ہوں) .\nاللہ کے لئے ایک دن روزہ رکھیں.\nکسی مسکین کو پھل یا گوشت کا صدقہ کیجئے.\nguid\nاللہ کے تقویٰ کے حریص بن جائیے اس کی جنت کی سعادت نصیب ہوگی.\nدنیا میں اللہ سے خوب زیادہ ڈرنے والے اور خوف کرنے والے بن کے رہیں جیسا کہ اللہ تعالیٰ نے جنتیوں کے بارے میں بتایا ہے کہ وہ دنیا کی اپنی اسی حالت کو (قیامت کے دن) بیان کریں گے.\nنیکی کے کاموں میں اپنے والدین کی مدد کیجئے یقیناً آپ کو ان کے ساتھ بلند مرتبہ میں ملادیاجائے گا.\nrefl\nٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ١٦ إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَنَعِيمٖ ١٦\nاللہ تعالیٰ نے جب مکذبین کو دی جانے والی سزا ذکر کی تو متقیوں کی نعمتوں کا بھی تذکرہ فرمایا تاکہ ترغیب و ترھیب دونوں باتوں کا ذکر آجائے اور دل امیدوخوف کے درمیان رہے ۔(السعدی:۸۱۴)\nاللہ تعالیٰ نے جھٹلانے والوں کی سزا کے بعد متقیوں کا انجام کیوں ذکر کیا؟\nإِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَنَعِيمٖ ١٧ فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ ١٨\nاور اس میں یہ نکتہ بھی ہے کہ جہنم کے عذاب سے انہیں بچانا عدل ہے کیونکہ انہوں نے ایسا کچھ کیا ہی نہیں جس پر سزا واجب ہوتی اور جو نعمتیں انہیں دی گئیں وہ اللہ کا فضل اور اس کی طرف سے عزت افزائی ہے ۔(ابن عاشور:۲۷؍۴۶)\nآیت کریمہ میں اللہ نے متقیوں کے لئے عدل وفضل دونوں کو کس طرح جمع فرمایا ہے ؟ وضاحت کیجئے ؟\nمُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ\nاللہ نے (سُرُرٍ) کی صفت (مَصْفُوْفَةٍ) بیان فرمائی ہے تاکہ معلوم ہوکہ وہ تخت زیادہ ہوں گے ، اچھی طرح مرتب ہوں گے، اچھے رہن سہن کے سبب وہ لوگ خوش ہوں گے اورتمام گھر والے اکٹھا ہوں گے ، اور ایک دوسرے سے گفتگو کا انداز بڑا پیارا ہوگا۔(السعدی:۸۱۵)\nسرر کی صفت مصفوفۃ سے بیان کرنے میں کئی امور کا پتہ چلتا ہے انہیں بیان کیجئے؟\nوَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۢ بِمَا كَسَبَ رَهِينٞ ٢١\nآیت کا معنی وہی ہے جو حدیث شریف میں موجودہے کہ رسول صلی اللہ علیہ وسلم نے فرمایا: اللہ مومن کی اولاد کو بھی مومن کے مقام تک بلند فرمادیتا ہے اگر چہ اولاد عمل میں اس سے کمتر ہو تا کہ ان کے ذریعہ مومن کی آنکھوں کو ٹھنڈک نصیب ہو ۔ تو یہ آباء کے سبب ابناء کی عزت افزائی ہے…اب اگر یہ کہا جائے (بِاِيْمَانٍ) کو نکرہ کیوں لایاگیا تو جواب یہ ہے کہ دراصل ایمان والی کوئی بھی چیز ان کے پاس اس درجے کی نہیں تھی جس سے وہ اپنے آباء کے مقام تک پہنچ سکتے مگر آباء کی عزت افزائی کے لئے ان کی اولاد کو ان کے ساتھ کردیاگیا ہے سو مراد اولاد کے ایمان کی قلت ہے البتہ درجہ ان کا بلند کردیا گیا۔ غور فرمائیے اگر عظیم ایمان ہوتا تب کیا بات ہوتی۔(وما ألتناهم من عملهم من شيء) یعنی ان کے اعمال کا ثواب ہم نے کچھ بھی کم نہیں کیا بلکہ انہیں ان کا پوراپورا اجر دیا۔(ابن جزی:۲؍۳۷۶)\nآیت میں اہل جنت کی دل بستگی کی تکمیل کا بیان ہے اسے بیان کیجئے؟\nقَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ ٢٦ فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ ٢٧\nآیت کریمہ میں یہ بات بھی موجود ہے کہ دنیا والے گھر میں اللہ کے عذاب سے سخت خوف کھانا آخرت میں خوف سے محفوظ رہنے کا سبب ہے۔ اس کا مفہوم مخالف یہ ہوا کہ جو دنیا میں عذاب الٰہی سے خوف نہیں کھاتا آخرت میں اس سے نہیں بچ سکتا۔(الشنقیطی:۷؍۴۵۶)\nعذاب آخرت سے چھٹکارے کی علت بتائیے؟ اور آیت سے کیا سمجھ میں آتا ہے ؟\nقَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ ٢٦\n(مُشْفِقِيْنَ) یعنی ڈرنے اور خوف سے کانپنے والے تھے ۔ چنانچہ اس کے ڈر سے ہم نے گناہ چھوڑدیا اور اس کی وجہ سے ہم نے عیوب کی اصلاح کرلی ۔ (السعدی:۸۱۵)\nاللہ اور آخرت کا خوف انسان کے لئے کب مفید ثابت ہوتا ہے ؟\nإِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ ٢٨\nآسمان و زمین میں جولوگ بھی ہیں سب اللہ سے مانگتے ہیں لیکن کامیابی اور نجات عبادت میں اخلاص پیدا کرنے پر ملتی ہے خالی مانگنے اورطلب کرنے سے نہیں۔(ابن القیم:۳؍۶۲)\nاللہ سبحانہ و تعالیٰ سے دعا تو پوری مخلوق کرتی ہے مگر وہ کون ہے جو چمڑیاں جھلسادینے والے عذاب سے نجات پائے گااور بچ سکے گا؟\nwords\nاصلَوهَااس ميں داخل هو جاؤ۔ اس كي گرمي كا مزه چكھو.\nمَصفُوفَةٍصف به صف ؛ آمنے سامنے.\nبِحُورٍحور/ سفيد خواتين.\nرَهِينٌگروي ركھا هوا؛اپنے عمل كے بدله.\nيَتَنَازَعُونَوه ايك دوسرے پر زيادتي كرتے هيں.\nلاَ لَغوٌ فِيهَااس كے پينے سے كوئي گري هوئي بات نه كرے گا.\nوَلاَ تَأثِيمٌاور اس كے سبب سے قولي يا فعلي گناه نه هوگا.\nمَكنُونٌچھپا هوا/ مستور.\nعَذَابَ السَّمُومِآگ كا عذاب."],[525,"§الطور\ndeeds\nدشمنان دین کی کسی چال پر توجہ مرکوز رکھیں اور اللہ سے دعا کریں کہ اللہ ان کامکر انہی پر پلٹ دے.\nنماز فجر کی حرص پیدا کریں.\nصبح و شام کے اذکار کی پابندی کیجئے.\nguid\nانبیاء علیہم السلام اپنے دعوتی عمل پر معاوضہ نہیں لیتے.\nاللہ نے جس کے دل کی صلاحیت مٹادی ہو وہ ڈرانے والی تنبیہات سے فائدہ نہیں اٹھا سکتا.\nمسلمان کو قلبی سکون حاصل کرنے کے لئے تسبیح اور عبادت کی بڑی اہمیت ہے.\nrefl\nأَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ ٣٢\nحلم کا معنی عقل ہے ۔ (أم تأمرهم أحلامهم) ‘‘کیا ان کی عقلیں انہیں یہی سکھاتی ہیں’’ کے اسلوب میں انکار کا مفہوم یہ ہے کہ عالی دماغوں سے ایسی بات سرزد نہیں ہوسکتی۔ اس میں یہ تنقید ہے کہ ان کی عقل ماری گئی ہے تبھی وہ لوگ ایسی بات کررہے ہیں ۔ کیونکہ صحیح عقل ودماغ سے ایسی بات صادر نہیں ہوسکتی۔سووہ ایسے ہیں گویاان کے پاس عقل ہی نہیں ہے ۔ اور بات جوکہی جاتی ہے کہ کافر بے عقل ہوتا ہے اس کا یہی مطلب ہے۔(ابن عاشور:۲۷؍۶۴)\n‘‘ کافر بے عقل ہوتاہے’’ اس قول کی شرح کس طرح کی جائےگی؟\nأَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ ٣٢\nیعنی کیا ان کی عقلیں انہیں ایسی ہی متضاد باتیں سکھاتی ہیں۔ بے شک! کاہن تو وہ ہے جو ذہانت و فطانت میں بہت بڑھا ہوا ہو۔ اور مجنوں بے عقل آدمی کو کہتے ہیں چہ جائے کہ وہ ذہین و فطین ہو۔(الشوکانی :۵؍۹۹)\nرسول گرامی صلی اللہ علیہ وسلم کو الزام لگانے میں مشرکین کا تناقض کیا ہے بیان کریں؟\nفَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ ٣٤\nاللہ کےفرمان: (إن كانوا صادقين) یعنی اگر وہ اپنے اس گمان میں سچے ہیں کہ آپ نے جھوٹ بات منسوب کیا ۔ یعنی اگر وہ قرآن جیسا کلام پیش نہ کرسکے تو پھر جھوٹے ہیں۔ اور یہ آیت ان کی عزیمتوں کوگویابھڑکارہی ہے کہ وہ قرآن جیسا کلام پیش کریں۔ تاکہ جب وہ قرآن جیسا کلام پیش نہ کرسکیں تو یہ چیز ان کے جھوٹ کی کھلی ہوئی دلیل بن جائے ۔ (ابن عاشور:۲۷؍۶۷)\nآیت میں (إن كانوا صادقين) کہنے کا کیافائدہ ہے ؟\nفَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ ٣٤\nیہ چیز خلاف عادت ہے کہ کسی قوم کا کوئی شخص کچھ ایسا پیش کرے جس کی مثال پوری قوم پیش کرنے سےعاجز ہوحالانکہ وہ شخص ان ہی جیسا ہو۔عقل مند شخص کسی چیز کی واقفیت کےبغیر حتمی انداز نہیں اختیار کرتا۔ چونکہ انہیں اس کا علم تھا لہٰذا انہیں آپ جیسا کلام پیش کرنے پر قادر بھی ہونا چاہئے۔اللہ کے رسول فصاحت،وطن اور نسب میں انہی جیسے تھے اور کفار مکہ میں بعض تو تحریر ،شعر گوئی ، علماء کی ہم نشینی ، مراسلات اور تقریروں کی مشق وغیرہ میں آپ سے آگے تھے۔ سو جس بات سے وہ لوگ عاجز ہیں اس بات پر اگر آپ قادر ہیں تو اس کا صاف مطلب ہے کہ یہ صرف اللہ کی تائید و نصرت کا معاملہ ہے۔ ان کی تکذیب سے یہی بات مراد ہے۔(البقاعی:۱۹؍۲۶)\nآیت میں آپ کی رسالت کی سچائی پر کھلی دلیل موجود ہے اس کی وضاحت کیجئے ؟\nيَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ ٤٦\n(شيئًا) یعنی کم نہ زیادہ، بھلے دنیا میں ان کے یہاں مکر پایا جاتا ہے اور اس کے سہارے ایک مختصر مدت وہ گزار بھی لیتے ہیں لیکن روز قیامت ان کا مکر بےکارہوجائے گااور ان کی ساری کوشش برباد ہوجائے گی۔(السعدی:۸۱۸)\nدنیا اور آخرت میں کفار کے مکر کا فرق واضح کیجئے ؟\nوَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٤٧\nایک قول یہ ہے کہ یہاں ان کی مو ت سے پہلے عذاب مراد ہے ۔ ابن زید کےمطابق عذاب سے: مال واولاد کی تباہی، پریشانیاں ،بیماریاں ،تکلیفیں وغیرہ دنیا کے مصائب مراد ہیں ۔(القرطبی:۱۹؍۵۴۱)\nمخالفت کرنے والے پر صرف آخرت کا عذاب نہیں ہوگا ۔ اس کی وضاحت فرمائیں؟\nوَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ ٤٩\n(رات میں تسبیح پڑھئے اور ستاروں کے ڈوبتے وقت بھی) بایں طور کہ فجر کی سنت اور فرض ادا کیجئے، کیونکہ ستاروں کے غروب ہونے کا حقیقی وقت یہی ہوتا ہے، گویا صبح کی عبادت پر (یہاں) دو مربتہ ابھارا گیا ہے اس کی قدر و منزلت بیان کرنے کے لئے، کیونکہ یہ واقع ہونے والے عذاب سے نجات دلاتا ہے اور زرہ پوش دشمن پر غلبہ عطاکرتا ہے، خواہ وہ کھلم کھلا حملہ آور ہو، یا دھوکہ باز منافق ہو۔ (البقاعی:۱۹؍۳۹) (توضیح از مترجم: صبح کی عبادت پر دوبارہ ابھارا گیا ہے ایک (حِيْنَ تَقُوْمُ) میں اور دوسرا (ادبار النجوم) میں)۔\nسورج ڈوبنے کے وقت کو نماز اور تسبیح کے لئے کیوں خاص کیاگیا ہے؟\nwords\nأَحلاَمُهُمان كي عقليں.\nطَاغُونَنافرماني ميں حد سے تجاوز كرنے والے.\nتَقَوَّلَهُاس نے اپني طرف سے گھڑ ليا هے.\nمِن مَغرَمٍتاوان /جس كا ان سے مطالبه هے.\nكَيدًامكر چالبازي.\nكِسفًاٹكڑا.\nمَركُومٌايك دوسرے پر تهه لگے هوئے.\nيُصعَقُونَوه هلاك كئے جاتے هيں / بيهوش كئے جاتے هيں.\nوَإِدبَارَ النُّجُومِاور ستاروں كے پلٹنے كے وقت(وقت فجر)."],[526,"§النجم\ndeeds\nاسراء اور معراج میں جو کچھ ہوا ہے اسے پڑھئے جیسا کہ اس بابت آپ صلی اللہ علیہ وسلم نے خبر دی ہے.\nاللہ سے ہدایت ،پاکیزگی، بےنیازی کا سوال کیجئے.\nاذان کے بعد یہ دعا پڑھئے: ‘‘اَللّٰهُمَّ رَبَّ هٰذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ القَائِمَةِ اٰتِ مُحَمَّدًا الْوَسِيْلَةَ وَالفَضِيْلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِیْ وَعَدْتَهُ’’‘‘اے اللہ! اس بھر پور پکار اور قائم نماز کے رب! محمد صلی اللہ علیہ وسلم کو وسیلہ اور فضیلت عطا فرما اور انہیں وہ ‘‘مقام محمود’’ عطا کردے جس کا تونے ان سے وعدہ فرمایا ہے’’ ۔ تاکہ اس کے سبب نبی محمد صلی اللہ علیہ وسلم آپ کی شفاعت کریں.\nguid\nہمارے نبی صلی اللہ علیہ وسلم کا بلند و بالا مقام ہے.\nحضرت جبرئیل پر ایمان لانا، ان سے محبت کرنا اور یہ عقیدہ رکھنا کہ انہوں نے ہی رسول صلی اللہ علیہ وسلم کے پاس وحی پہنچایا ہے.\nکفار کا اللہ تعالیٰ کی عزت نہ کرنا.\nrefl\nوَٱلنَّجۡمِ إِذَا هَوَىٰ ١ مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ٢\nاللہ کی جو کچھ وحی رسول صلی اللہ علیہ وسلم لے کر آئے ہیں اس کی صحت پر ستاروں کی قسم کھائی گئی ہے۔ کیونکہ اس میں ایک عجیب مناسبت یہ ہے کہ جس طرح اللہ نے ستاروں کو آسمان کی زینت بنایا ہوا ہے اسی طرح وحی اور وحی کے آثار بھی زمین کی زینت ہیں۔چنانچہ انبیاء کرام کا موروثی علم نہ ہوتا تو لوگ کالی رات کےاندھیروں سے بھی سخت تاریکی میں رہتے۔\nستاروں اور نبی کی نبوت کے درمیان کیا تعلق ہے ؟\nمَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ٢\nیہ قسم کا جواب ہے اور یہاں قریش سے خطاب ہے۔ اور (صَاحِبُكُمْ) یعنی تمہارے ساتھی سے مراد نبی ہیں۔ تو اللہ نےآپ صلی اللہ علیہ وسلم سے یہاں گمراہی اور بے راہ روی کی نفی فرمائی ہے ۔ دراصل ‘‘ضلال’’ و‘‘غى’’ کے درمیان معنوی فرق ہے ۔ ‘‘ضلال’’ میں ارادہ نہیں ہوتا ہے ۔ جبکہ ‘‘غى’’ میں ارادہ ہوتا ہے اور باقاعدہ گمراہی حاصل کی جاتی ہے ۔ (ابن جزی:۲؍۳۸۰)\nگمراہی (ضلال) اور بے راہ روی (غوایت) میں کیا فرق ہے ؟\nمَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ٢ وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ ٣ إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ ٤\nاللہ نے آپ صلی اللہ علیہ وسلم سے غی و ضلال یعنی گمراہی اور بے راہ روی کی نفی فرمائی اور آپ کی صفت یہ بیان فرمائی: (وما ينطق عن هوى .. إن هو إلا وحي يوحى) کہ آپ خواہش نفس (ھوی)سے نہیں بولتے ۔ جو کچھ کہتے ہیں سب اللہ کی طرف سے وحی ہوتی ہے ۔تو آپ سے ھوی یعنی خواہش نفس کی نفی کی اور مکمل علم کا اثبات کیا گیا اور وہ ہےوحی۔چنانچہ یہ علم کا کمال ہوا اور وہ (یعنی غی و ضلال سے نفی) قصد کا کمال ہوا ۔ اور آپ کے دشمنوں کو ان دونوں کی ضد سے متصف فرمایا : تو انسان کے حق میں کمالِ مطلق کا معنی ہے : علم و ارادہ دونوں سے بندگی کی تکمیل ۔(ابن تیمیہ:۶؍۱۲۸)\nان آیات سے نبی صلی اللہ علیہ وسلم کے کمال اور مشرکین کے نقص کا ثبوت ملتا ہے اس کی وضاحت کریں ؟\nوَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ ٣ إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ ٤\nاس سے پتہ چلتا ہے کہ سنتِ رسول اللہ کی طرف سے رسولِ گرامی پر وحی ہے۔(السعدی:۸۱۸)\nاس آیت سے مقام سنت کی وضاحت کس طرح ہورہی ہے بیان کریں؟\nمَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ ١٧\nبادشاہوں اور رئیسوں کے دربارمیں حاضر ہونے والے ادب سے عاری شخص کو جو معاملہ پیش آتا ہے خواہ وہ دائیں بائیں دیکھنے کی بات ہو یا بے ڈھنگے طریقے سے سامنے نگاہ ڈالنی ہو اللہ نے اپنے نبی صلی اللہ علیہ وسلم سے ان تمام چیزوں کی نفی فرمائی ہے۔ اور اس جلوہ گاہ اور مقام میں کمال ادب کی خبر دی ہے کہ آپ صلی اللہ علیہ وسلم نےنہ تو ادھر ادھر التفات فرمایا، نہ آیات اور وہاں کے عجائبات سے آپ کی نگاہ ہٹی بلکہ اس غلام کی طرح حاضر ہوئے کہ اسے جو سکھا دیا گیا ہو اسی طرح خاموش اور متوجہ ہو کر کھڑے رہے۔نہ ادھر ادھر دیکھے، نہ ان میں تانک جھانک کرے جو اس نے نہیں دیکھا ہوا ہے ۔ ادب کے ان تقاضوں کے ساتھ ساتھ آپ کا دل پر سکون اور مطمئن تھا اور طبیعت میں ٹھہراؤتھا اور یہ چیز کمال (بندگی) کی انتہا ہے۔(ابن القیم :۳؍۷۶)\nآیت اسراء و معراج کے موقع سے نبی صلی اللہ علیہ وسلم کے کمال ادب کا پتہ دیتی ہے اس کی وضاحت فرمائیں؟\nإِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ\nیعنی برائی پر ابھارنے والے،ان کے نفس میں جو بھی خواہش ابھرتی ہے وہ اس کی پیروی کرتے ہیں۔ دراصل نفس کا معاملہ یہ ہے کہ اس میں غیر افضل چیزوں کی چاہت پیدا ہوتی ہےکیونکہ اسے لذت آفریں چیزوں کی عادت ہے البتہ عقل نفس کو اچھے انجام کی طرف لے جاتی ہے ۔(الألوسی:۱۴؍۵۸)\nانسان کس طرح اس آیت کی روشنی میں اپنی تربیت کرے؟\nوَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ ٢٣\nعقل کا تقاضا ہے کہ ہدایت جسے بھی نظر آئے وہ اس کی پیروی کرے خواہ وہ اس کے دشمن کی طرف سے ہی کیوں نہ آئی ہو۔ جب بات ایسی ہے تو پھر اطاعت کا کیا انداز ہونا چاہئے اگر وہ ہدایت اس سے افضل شخص لے کر آئے، اس ذات کی طرف سے جن کا احسان کبھی منقطع نہیں ہوگا۔(البقاعی:۱۹؍۶۱)\n(ولقد جاءهم من ربهم الهدى) کہہ کر اللہ نے جو خبر دی ہے اس میں کیا بات ہے ؟\nwords\nوَالنَّجمِ إِذَا هَوَىاور ستارے كي قسم جب وه ڈوب جائے/ غائب هو جائے.\nوَمَا غَوَىاور كبھي باطل اعتقاد نهيں ركھا.\nذُو مِرَّةٍصاحب قوت اور خوبصورت منظر والا.\nأَفَتُمَارُونَهُكيا تم اس سے جھگڑتے هو (يعني محمد صلی اللہ علیہ وسلم سے).\nسِدرَةِ المُنتَهَىبيري كا آخري درخت؛ ساتويں آسمان پر۔ زمين سے آسمانوں كي طرف چڑهنے والي چيزيں يهاں تك هي پهنچتي هيں۔ يهاں عالم بالا سے احكام آتے هيں."],[527,"§النجم\ndeeds\nکوئی قرآنی حلقہ یا علمی مجلس تلاش کیجئے اور کچھ ہی دیر کیوں نہ ہو اس میں بیٹھئے.\nدعا پڑھئے : ‘‘اَللّٰهُمَّ حَبِّبْ اِلَيَّ الْاِيْمَانَ وَزَيِّنْهُ فِيْ قَلْبِيْ وَكَرِّهْ اِلَيَّ الْکُفْرَ وَالْفُسُوْقَ وَالْعِصْيَانَ’’:‘‘الٰہی ایمان کو میرے لئے محبوب کردے اور میرے دل میں اسے مزین فرمادے۔ کفر،فسق اورنافرمانی سے نفرت پیدا کردے’’.\nاپنے شہر میں موجود کسی بڑے گناہ کو نظر میں رکھیں اور بعض ایسے مرتکبین کو تنبیہ کریں جنہیں آپ جانتے ہوں.\nguid\nیہ بات یاد رکھیں کہ اللہ تعالیٰ گمراہ اور ہدایت یاب کو بخوبی جانتا ہے.\nاس سورت کے ذریعہ اللہ کی رحمت و مغفرت میں جو وسعت ہے اس کی معرفت حاصل کیجئے.\nانسان کو اس کے ہر عمل کا بدلہ ملے گا خواہ عمل اچھا ہو یا بر اہو.\nrefl\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ ٢٧\nایمان نہ ہونے کی وجہ سے ان میں یہ جرأت پیدا ہوئی کہ وہ اللہ و رسول کے خلاف کچھ کہنے اور کرنے کی ہمت کر سکیں۔ مثلاً ان کا یہ کہنا کہ ‘‘فرشتے اللہ کی بیٹیاں ہیں’’۔ (السعدی:۸۲۰)\nوہ کیا وجہ تھی کہ مشرکین کے اندر اللہ و رسول کی مخالفت کی ہمت ہوگئی تھی اور فرشتوں کی بابت وہ بیہودہ گوئی کرتے تھے؟\nفَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ٢٩\nان کے بربادحواس اور ان کی گمراہی کا ذکر کرنے کے بعد اس ضمن میں اللہ نے اپنے نبی کو ان سے اعراض کرنے کا حکم فرمایا۔ اعراض کے حکم کی وجہ یہ ہوئی کہ ان کی گمراہی کا ہر رنگ اللہ کے ذکر سے اعراض کرنے کا نتیجہ تھا ،مطلب یہ ہے کہ اللہ کے ذکر سے وہ پیٹھ پھیر لیتے تھے۔ سو مناسب ہوا اس اعراض کا بدلہ یہ دیاجائے کہ نبی صلی اللہ علیہ وسلم بھی ان سے اعراض فرمائیں ۔(ابن عاشور:۲۷؍۱۱۷۔۱۲۲)\nاس آیت سے ہم یہ کیسے جان سکتے ہیں کہ جیسا کام ہوگا بدلہ بھی ویسا ہوگا؟\nوَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ٢٩ ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ\nیعنی یہی ان کی کل واقفیت ہے اور یہی ان کا مبلغ علم ہے ۔ رہے آخرت پر ایمان رکھنے والے اور اس کی تصدیق کرنے والے اصحاب عقل و خرد تو ان کا ارادہ اور ان کی تگ و دو آخرت کے لئے ہے ۔ان کے علوم سب افضل اور برتر ہیں ، وہ جو کتاب اللہ اور سنت رسول سے ماخود ہیں۔(السعدی: ۸۲۰)\nیہ آیت کریمہ شرعی علم کی فضیلت پر کس طرح دلالت کرتی ہے ؟\nذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ\nیعنی وہ صرف اپنی دنیا کے امور پر دھیان دیتے ہیں اور اپنے دین کے معاملہ سے جاہل ہیں ۔ فرّاء کہتے ہیں : اللہ نے انہیں معمولی بتلایا اور ان کی تحقیر فرمائی ۔ یعنی یہی ان کی عقل کا معیار ہے اور یہی ان کا مبلغ علم ہے کہ وہ دنیا کو آخرت پر ترجیح دیں۔(القرطبی:۲۰؍۴۱)\nیہ اسلوب اسلوب تحقیر و تصغیر کہلاتا ہے ۔ آپ یہ بتائیے اللہ نے کس چیز کے ذریعہ ان کا رتبہ گھٹایا ہے ؟\nوَإِذۡ أَنتُمۡ أَجِنَّةٞ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ\nاور جب تم اپنی ماؤں کے پیٹو ں میں‘‘جنین’’ تھے سوجس کامقدر ساقط ہونا تھا ساقط ہوگیا اور ہم لوگ پیٹ میں باقی رہنے والوں میں سے ٹھہرے۔ پھر ہم دودھ پینے کی عمر کو پہنچ گئے سو کچھ انتقال کرگئے اور ہم زندہ باقی رہنے والوں میں سے ٹھہرے۔پھرہم بالغ ہوگئے تو کچھ قوت ہوگئی اور ہم بچ رہے۔پھر ہم جوان ہوگئے سو کچھ تو وفات پاگئے اور ہم باقی رہے پھر ہم بوڑھے بھی ہوگئے۔حیرت کی بات ہے! اب بھلا ہمیں کس چیز کاانتظار ہے ؟ (البغوی:۴؍۲۶۱)\nاس آیت سے ہم پر اللہ تعالیٰ کا ایک احسان سمجھ میں آتا ہے بتائیے وہ کون سا احسان ہے؟ پھر وہ احسان ہمیں کس بات کی دعوت دیتاہے؟\nفَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ ٣٢\nکلبی اور مقاتل رحمہما اللہ فرماتےہیں : لوگ اعمال تو اچھے انجام دیتے مگر کہتے : ہماری نماز !ہمارے روزے! ہماراحج! ہمارا جہاد! چنانچہ اللہ نے یہ آیت نازل فرمائی : (هو أعلم بمن اتقى) یعنی اللہ کو خوب معلوم ہے کون نیک ہے اور فرمانبردار ی کررہا ہے اور خالص اللہ کے لئے کررہا ہے۔(البغوی: ۴؍۳۱۲)\n(فلا تزكوا أنفسكم) کا سبب نزول بیان فرمائیے؟\nوَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ ٣٩\nآخرت میں بیٹے باپ سے ملحق ہونگے جیسا کہ دنیا میں با پ کے ساتھ شامل مانے جاتے تھے۔ یہ شمولیت آباء کی عزت افزائی اور اس ثواب کا نتیجہ ہے جو ثواب انہوں نے اپنی کوشش سے حاصل کیا ہے ۔ البتہ بیٹوں کی باپوں کے ساتھ مراتب میں شمولیت بلا محنت حاصل ہوئی ہے سویہ بات بیٹوں کے لئے نہیں باپوں کے لئے ہے۔ اللہ نے جنت میں انہیں اولاد سے ملا کر ان کی آنکھ ٹھنڈی کردی۔(ابن القیم :۳؍۸۲)\n(وأن ليس للإنسان إلا ما سعى) اور ﴿وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ﴾ [الطور: ۲۱]میں کس طرح تطبیق دیں گے ؟\nwords\nبِالحُسنَىجنت كا.\nوَالفَوَاحِشَوه كبيره گناه جس كي قباحت بڑي هو.\nاللَّمَمَوه چھوٹے گناه جن پر اصرار نه كيا جائے.\nوَأَكدَىدينے سے رك گيا۔ بخل كي وجه سے نيكي چھوڑ دي.\nأَلاَّ تَزِرُ وَازِرَةٌكوئي گنهگار بوجھ نه اٹھائے گا.\nالمُنتَهَىتمام مخلوق كي انتهاء۔ قيامت كا دن."],[528,"§النجم ، القمر\ndeeds\nچند آیات کی تلاوت بےحد توجہ اور خاموشی کےساتھ سماعت کیجئے.\nسورہ نجم کی آخری آیات پر جب پہنچیں تو سجدہ تلاوت کریں.\nاپنے جان پہچان والوں سے چاندکے ٹکڑےہونے کا واقعہ بیان کیجئے؟\nguid\nاے اولاد آدم اپنی ناتوانی کا خیال کر کہ تو دوسروں کا کس قدر محتاج ہے.\nقرب قیامت پرایمان اہل ایمان کے لئے نیک عمل کا محرک ہوتا ہے.\nخواہشات کی پیروی انسان کو جھوٹ بولنے پر ابھارتی ہے.\nrefl\nوَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ ٥٢\nاس کی سب سے بڑی دلیل اللہ کا یہ فرمان ہے: ﴿فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامًا﴾ [العنكبوت: ۱۴] نوح علیہ السلام ان کے درمیان ساڑھے نو سوبرس رہے ۔کیونکہ جو قوم اتنے لمبے زمانے کے باوجود ایک بے حد مہربان اور خیر خواہ نبی کی دعوت سے اثر نہیں لے سکی تو اس میں کوئی شبہ نہیں کہ وہ سب سے زیادہ ظالم اور سرکش تھے۔(الطبری :۲۲؍۵۷۳)\nاللہ تعالیٰ نے قوم نوح کوسب سے زیادہ ظالم اور سرکش کیوں کہا؟\nوَأَنتُمۡ سَٰمِدُونَ ٦١\n(السمود) کامعنی ہوتاہے بے نیازی۔اور اس آیت میں سمود کا جو معنیٰ غفلت اور بھول کا بیان کیا گیا ہے اس میں کوئی تعارض نہیں ہے ۔کیونکہ بے نیازی ان تمام باتوں کو شامل ہے اور بے نیازی سے یہ تمام چیزیں ضرورواقع ہوں گی۔(ابن القیم :۳؍۸۵-۸۶)\nبعض سلف کے یہاں سمود غنا کے معنی میں ہے اور بعض سے یہ وارد ہےکہ غفلت کے معنی میں ہے تو آپ ان اقوال کے درمیان کیسے تطبیق دیں گے؟\nفَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩ ٦٢\nاللہ کے لئے سجدے کاخصوصی حکم اس کی فضیلت کا پتہ بتانے کے لئے ہے۔ اور یہی سجدہ عبادت کا خلاصہ اور اس کاراز ہے، سجدے میں دل اور بدن دونوں جھک جاتےہیں اور بندہ اپنے سب سے معززعضو(پیشانی) کو پیر سے روندنے والی حقیر زمین پر رکھ دیتاہے۔(السعدی:۸۲۳)\nاس آیت کی مدد سےعبادات کے درمیان سجدے کامقام آپ کس طرح سمجھ رہے ہیں ؟\nٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ ١\nاس معجزہ کو قرب قیامت سے جوڑکر نصیحت کاذریعہ بنایاگیاہے۔ مناسبت کچھ اس طرح ہےکہ چاند آسمانی کائنات کاحصہ ہے اور یہ چاند کاجو نظام ہے وہ زمینی کائنات کے نظام پر جاری وساری ہے چنانچہ آسمانی کائنات کے نظام میں اگر کوئی تبدیلی رونما ہوتی ہے تو وہ عام سی چیز نہیں ہے اس لحاظ سے یہ بات مناسب ٹھہری کہ اس دنیا میں توڑ پھوڑ کے امکانات سے لوگوں کو متنبہ کردیاجائے ۔آیت میں فعل ماضی کا استعمال حقیقی ہے۔(ابن عاشور :۲۷؍۱۶۸)\nاللہ کے فرمان: (اقتربت الساعة) اور پھر اس کے بعد (وانشق القمر)میں کیاتعلق ہے ؟\nٱقۡتَرَبَتِ ٱلسَّاعَةُ\n(اقتربت الساعة) کہہ کر اللہ تعالیٰ نے یہ بتانا چاہا ہےکہ وہ گھڑی قریب آچکی ہےجس میں قیامت قائم ہوگی یہ (اقتربت) اصل میں اِفْتَعَلَتْکے وزن پر ہے اور ‘‘قرب’’سے ماخوذ ہے ۔ اللہ کی جانب سے اس قربت کا ذکر قرب قیامت اور دنیا کی ہلاکت سے ڈرانے کے مفہوم میں ہے کہ اللہ تعالیٰ نے حکم فرمایا ہے لوگ قیامت کی ہولناکیوں کے پیش نظر اچانک آجانے سے پہلے اس کی تیاری کرلیں ورنہ یہ نہ ہو کہ قیامت آجائے اور وہ غفلت میں مست پڑے رہیں۔ (الطبری:۲۲؍۵۶۵)\nاللہ نے قرب قیامت کی جو خبر دی ہے اس کا فائدہ بتائیں؟\nوَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ ٣\nقشیری رحمہ اللہ کا کہناہے: خواہشات (هوی) کی پیروی کی نحوست سے تکذیب کا وجودہوتا ہے کیونکہ اللہ تعالیٰ خواہشات میں مبتلا شخص کے دل پر پردے ڈال دتیا ہے سووہ خیر وفلاح دیکھنے کی قوت کھوبیٹھتا ہے۔ اور رب کی رضا مندی کی اتباع تصدیق سے جڑی ہوتی ہے کیونکہ اللہ تعالیٰ اتباع حق کی برکتوں سے بصیرت کی آنکھیں کھول دیتاہے اور آدمی تصدیق کی توفیق پاجاتاہے۔ (البقاعی:۱۹؍۹۷)\nخواہشات کی اتباع کا نتیجہ ذکر کریں؟\nوَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ ٣\nیعنی ہر عمل اپنے عامل کو لے کر ٹھہراہوا پرسکون ہے۔ بھلائی بھلائی کرنے والے کو لےکر جنت ،اور برائی برائی کرنے والے کو لیکر جہنم میں۔ (القرطبی:۲۰؍۷۵)\n(وكل أمر مستقر) سے کیا مراد ہے؟\nwords\nأَغنَى وَأَقنَىاموال كا مالك بنايا؛ او راپني عطاء پر راضي كرديا.\nالشِّعرَىايك روشن ستاره ؛ اهل جاهليت اس كي عبادت كرتے تھے.\nوَالمُؤتَفِكَةَمدائن قوم لوط۔ ان بستيوں كو الله تعاليٰ نے الٹ ديا تھا.\nأَهوَىاوپر اٹھانے كے بعد زمين پر دے مارا.\nفَغَشَّاهَاانهيں چھپاديا / لباس پهنا ديا پتھروں كا.\nتَتَمَارَىتم شك كرتے هو (اے جھٹلانے والے انسان )."],[529,"§القمر\ndeeds\nاللہ سے دعا کریں کہ اللہ آپ کی پریشانی دور فرمادے.\nایک یا چند آیتیں متعین کرلیں پھر اس میں نصیحت کی جو باتیں اور مقاصد پائے جاتے ہیں ان میں غور کریں.\nیہ دعا پڑھئے: ‘‘اَللّٰهُمَّ اَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ’’: الٰہی میں تیری رضا کے ذریعہ تیری ناراضگی سے پناہ چاہتاہوں اور تیری عفوودرگزر کے ذریعہ تیری سزا سے پناہ چاہتا ہوں.\nguid\nنوح علیہ السلام پر اللہ کی خصوصی توجہ اور نگرانی تھی.\nنافرمانی اور جبر کا مظاہرہ کرنے والے پر اللہ کی سزا کا نزول.\nانبیاء اور ان کے متبعین کو آزمائش میں ڈالنا اللہ کی سنت ہے.\nrefl\nخُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ ٧\nنگاہ میں خشوع کا مطلب ہے نگاہ عاجزی کے ساتھ جھکی ہوتی ہے۔ خشوع کا نگاہ کےساتھ جو تعلق جوڑاگیا ہے اس کی وجہ یہ ہے کہ انسان کے دیکھنے کے انداز میں عزت و ذلت کا اثر نظر آتا ہے۔اللہ تعالیٰ کا فرمان ہے: ﴿أَبۡصَٰرُهَا خَٰشِعَةٞ﴾ [النازعات: ۹]، اور دوسری جگہ فرمایا: ﴿خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرۡفٍ خَفِيّٖ﴾ (الشوریٰ :۴۵) ذلت کے سبب ان کی نظریں جھکی ہوئی ہوں گی اور وہ کنکھیوں سے دیکھ رہے ہوں گے ۔(القرطبی:۲۰؍۷۸)\nخشوع کو ابصار کےساتھ کیوں جوڑا گیا؟\nيَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ ٨\nمفہوم اس کا یہ ہے کہ وہ دن مومنوں کے لئے آسان ہوگا۔(السعدی: ۸۲۵)\n‘‘وہ دن کافروں پرسخت ہوگا’’ یہ بتانے سے ہم کیا نتیجہ نکال سکتے ہیں؟\nفَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ ١٠\nیعنی میں ان کامقابلہ کرنے میں کمزور ہوں سو تو اپنے دین کی خاطر مددفرما۔(ابن کثیر:۴؍۲۶۵)\nدعوت الی اللہ میں اس آیت کے اندر دعا کی اہمیت کی جانب اشارہ موجود ہے اس کی وضاحت کیجئے؟\nوَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ١٧\nقشیری رحمہ اللہ فرماتے ہیں کچھ لوگوں کی زبان پر قرآن کی قرأت آسان ہے کچھ لوگوں کے دلوں کو اس کاعلم سہل ہے ، کچھ لوگوں کی عقل کےلئے اس کافہم آسان ہے، اور کچھ لوگوں کے ذہن میں اس کا حفظ آسان ہے اور سبھی قرآن والے ہیں اورسب اہل اللہ اور اللہ کے خاص بندے ہیں۔(البقاعی:۱۹؍۱۰۸)\nقرآن پاک میں آسانی کی صورتیں واضح کیجئے.\nوَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ١٧\nیعنی ہم نے قرآن کا حفظ آسان کردیا ہے اور یہ بات مشاہدے سے معلوم ہے۔ چنانچہ چھوٹے چھوٹے بچے اور ان کے علاوہ دوسرے لوگ بڑے پختہ انداز میں اسے یاد کرلیتے ہیں ۔ جبکہ قرآن کے علاوہ دیگر کتابوں کا معاملہ ایسا نہیں ہے۔ روایت ہے کہ اللہ کی کتابوں میں قرآن کے سوا کسی بھی کتاب کا زبانی حفظ ممکن نہ ہوا۔یوں بھی کہا گیا ہے کہ : آیت کا معنی دراصل یہ ہے کہ ہم نے قرآن کو سمجھنے اور نصیحت حاصل کرنے کے لئے آسان کردیا ہے کیونکہ قرآن میں دلائل اور بلیغ حکمتیں ہیں۔(ابن جزی:۲؍۳۸۹)\n؟ اللہ نے قرآن کو ذکر کے لئے کس طرح آسان فرمایا ہے.\nفَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ ١٦\nاس بلیغ آیت اور اللہ کے اس فرمان (فذوقوا عذابي ونذر) کی تکرار کا مقصد یہ ہے کہ سامع ہر قصہ کے وقت متنبہ ہوجائے اور اس سے نصیحت حاصل کرے کیونکہ ہر قصے میں کوئی نہ کوئی عبرت اور نصیحت موجودرہتی ہے سو ہر قصے کا خاتمہ کچھ اس طرح ہوتا ہے جس سے سامع وعید کے حوالے سے چوکنا ہوجائے ۔(ابن جزی:۲؍۳۸۹)\nاللہ نے ہر قصہ کے بعد (فكيف كان عذابي ونذر) کی تکرار کیوں فرمائی ہے؟\nوَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ١٧\nاللہ کے فضل سے دلوں کے لئے جس چیز کا حصول اور حفظ وفہم سب سے آسان ہے وہ اللہ کی کتاب ہے جسے اللہ نے برائے ذکر آسان فرمادیا ہے …اور جو چیز بے حد مشکل اور مشقت والی ہے وہ ہے لوگوں کی ذہنی صلاحیت ،مشکل سوالات ۔ اور اصول و فروع کی پیچیدہ صورتیں ہیں جن کے حق میں اللہ نے کوئی دلیل نازل نہیں فرمائی ہے ۔ (ابن القیم :۳؍۸۷)\nعلم و عمل کے لئے سب سے آسان مصدر کون سا ہے ؟\nwords\nخُشَّعًاشدت هولناكي سے پست هوكر.\nالأَجدَاثِقبريں.\nمُهطِعِينَجلدي كرنے والے..\nوَازدُجِرَاسے ڈانٹا گيا؛ او رتبليغ سے روكا گيا.\nمُنهَمِرٍموسلا دھار برسنے والا.\nقُدِرَمقرر شده۔ جو الله تعاليٰ نے ازل ميں مقرر كرديا؛يعني طوفان سے هلاكت.\nعَلَى ذَاتِ أَلوَاحٍ وَدُسُرٍوه كشتي جو تختيوں والي اور ميخوں والي تھي.\nمُدَّكِرٍنصيحت حاصل كرنے والا.\nيَومِ نَحسٍنحوست كا دن."],[530,"§القمر\ndeeds\nزبان سے خود پر اللہ کی نعمتوں کا شکر ادا کیجئے ۔ اور اطاعت کے اعمال میں سے کسی اطاعت کے ذریعہ اللہ کی قربت حاصل کرکے عمل سے شکرادا کیجئے.\nاس صفحہ کی آیتیں پڑھنے کےد وران دو فوائد کا استخراج کیجئے ؟\nکسی شخص سے جہنم کی ہولناکیاں بیان کیجئے یا اس بابت کوئی تحریر رقم فرمائیے؟\nguid\nجھٹلانے اور نافرمانی کرنے والوں پر اللہ کی سزا نازل ہونے کی بابت چوکنا رہنا.\nاللہ کے وعدہ اور اس کی مدد پر یقین رکھئے.\nقضاء و قدر پر ایمان.\nrefl\nفَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ٢٩\nاونٹنی کی کوچیں کاٹنے والے کو (صَاحِبَهُمْ) ان کا ساتھی کہا، اس بات کی جانب اشارہ کرنے کے لئے کہا کہ قو م ثمود اس کے عمل سے راضی تھے یوں وہ لوگ اس مجرم کے ساتھی اور اس کی طرف میلان رکھنے والے ٹھہرے۔ (ابن عاشور:۲۷؍۲۰۱)\nقوم ثمود اونٹنی کی کوچیں کاٹنے والے کے عمل کےحامی تھے اس پر کیا دلیل ہے ؟\nإِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطٖۖ نَّجَّيۡنَٰهُم بِسَحَرٖ ٣٤ نِّعۡمَةٗ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ ٣٥\nقشیری رحمہ اللہ فرماتے ہیں : نقصانات دور کرنے کی نعمت حصول نفع کی نعمت کے مقابلے زیادہ مکمل ہے ۔ یہ بات صرف ہوشیار با توفیق ہی جان سکتا ہے ۔ (البقاعی :۱۹؍۱۲۵)\nنعمتوں کی اقسام بیان کیجئے؟ اور یہ بتلائیے کہ کون سی نعمت شکر کی زیادہ مستحق ہے ؟\nوَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ ٣٦\n(بطشتنا) یعنی ہماری عظیم اور سخت پکڑ سے انہیں ڈرایا۔ (بطشة) واحد استعمال کیا ہے یہ بتانے کے لئے کہ اللہ کا کوئی بھی عذاب معمولی نہیں ہوتا ہے ۔اللہ کی عظمت کے سبب ایک ہی پکڑ کافی ہوجاتی ہے ۔ اس لئے لفظ کو تثنیہ استعمال نہیں کیا۔(البقاعی: ۱۹؍۱۲۵)\n(بطشتنا)واحد کیوں استعمال فرمایا؟\nفَذُوقُواْ عَذَابِي وَنُذُرِ ٣٧\nعذاب کی بابت ‘‘ذوق’’ یعنی چکھنے کا حکم بطور خاص دیاہے وجہ یہ ہے کہ وہ لوگ اپنی گندی حرکتوں سے خوب لذ ت حاصل کرتے تھے۔(البقاعی: ۱۹؍۱۱۳)\nقوم لوط کے قصے میں (فذوقوا عذابي ونذر) کاذکر خصوصیت کے ساتھ کیوں ہوا؟\nإِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلٖ وَسُعُرٖ ٤٧\n(إن المجرمين) یعنی وہ لوگ جنہوں نے جرائم کاارتکاب بہت زیادہ کیا۔ مطلب شرک اور دوسرے بڑے بڑے گناہ! (في ضلال وسعر) یعنی وہ لوگ دنیا میں گمراہ ہی رہے خواہ علم کی گمراہی ہو یاعمل کی۔ جس سے ہی انہیں عذاب سے نجات ملتی ۔ اور روز قیامت وہ دردناک عذاب میں ہونگے۔ (السعدی:۸۲۷)\nدنیا میں مجرمین کی گمراہی کی صورتوں میں سے دو صورت کا تذکرہ کیجئے ؟\nيَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ\nچہرہ تمام اعضاء میں سب سے معزز ہوتاہے ۔ اور چہرے کی تکلیف دوسرے اعضاء کی تکلیف سے سخت ہوتی ہے اس لئے انہیں چہرے کے عذاب سے بے عزت اور رسوا کیا جائے گا۔(السعدی:۸۲۸)\nمجرمین کو اس طرح عذاب دینے میں جسمانی تکلیف کے ساتھ نفسیاتی الم بھی ہے ۔ آیت سے جو آپ نے سمجھا ہے اس کی روشنی میں اسے بیان کیجئے؟\nwords\nشِربٍپاني پينے كي باري.\nفَتَعَاطَىاس نے اونٹني كو اپنے هاتھ سے پكڑا.\nفَعَقَرَاسے نحر كرديا(كونچيں كاٹ ديں).\nكَهَشِيمِ المُحتَظِرِجيسے وه خشك كھيتي جسے جانور روندڈاليں.\nحَاصِبًاپتھر.\nفَتَمَارَواوه شك ميں پڑ گئے انهوں نے جھٹلايا.\nأَدهَى وَأَمَرُّبهت سخت اور بهت كڑوي / عذاب بدر سے بھي سخت.\nوَسُعُرٍاور عذاب."],[531,"§القمر ، الرحمن\ndeeds\nیہ دعا پڑھئے : ‘‘اَللّٰهُمَّ اِنِّيْ اَسْئَلُكَ الْجَنَّةَ وَ نَعِيْمَهَا وَمَا قَرَّبَ اِلَيْهَا مِنْ قَوْلٍ وَ عَمَلٍ’’: الٰہی میں تجھ سے جنت کا سوال کرتا ہوں۔ اس کی نعمتوں کا سوال کرتاہوں۔ اس قول و عمل کی توفیق مانگتاہوں جو جنت سے قریب کرے.\nاللہ کی تعریف کیجئے کہ اس نے آپ کو قرآن سکھلایا.\nکوئی ایسی اہم نعمت یاد کیجئے جو اللہ نےآپ کو بطور خاص عنایت کیا ہو پھر اس پر اللہ کا شکر ادا کیجئے.\nguid\nقرآن سیکھنا فصاحت اور حسن بیان کا ایک راستہ ہے.\nآسمان و زمین عدل سے قائم ہیں ۔ اور ترازو اس کے ذرائع میں سےہے.\nاللہ کی متعدد نعمتوں کا شکر ادا کیجئے.\nrefl\nوَلَقَدۡ أَهۡلَكۡنَآ أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرٖ ٥١\n(ولقد أهلكنا أشياعكم) مرادوہ گزشتہ امتیں ہیں جنہوں نے وہی کچھ کیاجو تم نے کیا ہے ۔اور انہوں نے جھٹلایا جیسا تم جھٹلارہے ہو۔(فهل من مدَكِر) مد کر یعنی کوئی نصیحت حاصل کرنے والا ہے ؟ جو اس بات کا شعور رکھتا ہو کہ اگلے پچھلےتمام لوگوں میں اللہ کی سنت ایک ہی ہے اگر اس کی حکمت ان بد قماشوں کی ہلاکت کا تقاضا کرتی تو یہ لو گ بھی انہیں لوگوں جیسے ہیں ۔دونوں گروہوں میں کوئی فرق نہیں ہے۔ (السعدی:۸۲۸)\nاللہ تعالیٰ نے پچھلی امتوں کی ہلاکت کے واقعات کو کیوں بیان کیا؟\nفِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۢ ٥٥\n(مقتدر) کامطلب ہےاس کی قدرت ہر گوشے اور ہر سمت کو شامل ہے اور اس حد تک اس کی قدرت کی پہنچ ہے جس کا ادراک صرف اللہ سبحانہ وتعالیٰ کے لئے ہی ممکن ہے ۔ جیسا کہ ابھی قریب میں بات گزر چکی ہے۔ چنانچہ وہ انہیں ہر خیر تک پہنچاتا ہے اور ان سے ہر شر کو ہٹاتا ہے۔سو اس مبارک نام میں ظالموں کو سر کرنے کے حوالے سے ایک راز ہے ۔ (البقاعی:۱۹؍۱۳۷)\nاللہ کی صفت (مُقْتَدِر) کا مطلب بیان کریں؟\nفِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۢ ٥٥\nصادق رحمہ اللہ فرماتےہیں: اللہ نے مکانِ صدق کی تعریف فرمائی ہے سو سچے لوگوں کے سوا وہاں کوئی بیٹھنے نہ پائے گا۔(القرطبی:۲۰؍۱۰۹)\nآیت صدق کے مقام پر کس طرح دلالت کرتی ہے ؟\nٱلرَّحۡمَٰنُ ١ عَلَّمَ ٱلۡقُرۡءَانَ ٢ خَلَقَ ٱلۡإِنسَٰنَ ٣ عَلَّمَهُ ٱلۡبَيَانَ ٤\nاللہ نے تعلیم قرآنی کو تخلیق انسانی سے جوڑ کر ذکر فرمایا: فرمایا (خلق الإنسان)کیونکہ انسان پراصل نعمت یہی قرآن کی تعلیم ہے پھر اس کے بعد جن نعمتوں کا بیان کرنا چاہا بیان کیا کیونکہ وہ عظیم نعمتوں میں شمار ہیں ۔ (الألوسی:۱۴؍۹۹)\nتعلیم قرآنی کی نعمت دیگر نعمتوں سے پہلے کیوں بیان فرمایا؟\nعَلَّمَ ٱلۡقُرۡءَانَ ٢\nاس سورت میں ان مختلف نعمتوں کو شمار کردیا گیا ہے جو اللہ نے اپنے بندوں کو عطا فرمائی ہیں اور اس نعمت کو سب سے پہلے بیان کیا جو سب سے زیادہ مقدس، مفید، مکمل، نفع بخش، عظیم ترین بچت کی حیثیت رکھتی ہے، یہ نعمت تعلیم قرآن کی نعمت ہے ۔دراصل یہ نعمت ایسی نعمت ہے جس پر دنیا و آخرت کی سعادت کا مدار ہے اور دونوں کی بھلائیوں کی اصل اور دونوں امور کا ستون ہے ۔(الشوکانی :۵؍۱۳۱)\nسورہ رحمان کی ابتداتعلیم قرآن سے کیوں کی گئی ہے؟\nوَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ ٩\nقتادہ رحمہ اللہ اس آیت کے حوالے سےفرماتےہیں :’’ اے آدم کی اولاد عدل کر!جس طرح تجھے یہ پسند ہے کہ تیرے ساتھ عدل کیا جائے ۔اور وفاداری کر جس طرح تجھے اپنے ساتھ وفاداری محبوب ہے ۔ کیونکہ عدل میں لوگوں کے لئے خیر و صلاح ہے۔(القرطبی:۲۰؍۱۱۸)\nآیت کون سی رہنمائی پر مشتمل ہے بیان کیجئے ؟\nوَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۢ بِٱلۡبَصَرِ ٥٠\n(وما أمرنا إلا واحدة)سے مراد (مرة واحدة) یعنی ایک دفعہ ہے (كلمح بالبصر) یعنی مخلوق کی بابت میرا فیصلہ پلک جھپکنے سے بھی زیادہ تیز ہوتا ہے ۔ (لمح) کہتے ہیں :اچٹتی نگاہ ڈالنے کو۔(البغوی:۲ ؍۱۰۷)\nاس سورہ کو پڑھنے کے دوران جھٹلانے والی امتوں کے بارے میں اللہ کے فیصلوں کی کوئی مثال ذکر کیجئے؟\nخَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ كَٱلۡفَخَّارِ ١٤ وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجٖ مِّن نَّارٖ ١٥\nیہاں مٹی سے پیدا شدہ مخلوق انسان کی عنصریت کا شرف معلوم ہوتا ہے۔ وہ مٹی جو منافع ،بوجھ اورمضبوطی کا محل ہے برخلاف جناتوں کے عنصر کے کہ وہ آگ ہے جو برائی وفساد اور غصہ و ہلکاپن کا محل ہے ۔ (السعدی:۸۲۹)\nدونوں آیتیں انسان کی عظمت اور جناتوں پر اس کی فضیلت پر دلالت کرتی ہیں اس کا سبب بیان کیجئے؟\nwords\nإِلاَّ وَاحِدَةٌمگر ايك هي قول.\nمُستَطَرٌلكھا هوا؛ - ان كے اعمال ناموں ميں.\nمَقعَدِ صِدقٍمجلس حق؛ جس ميں كوئي لغو يا گناه كي بات نه هو.\nبِحُسبَانٍايك پخته حساب كے ساتھ (آگے پيچھے چلتے هيں ).\nوَضَعَهَا لِلأَنَامِاسے بچھا ديا (آسان كرديا) مخلوق كے ليے.\nالأَكمَامِوه برتن جن ميں كھجور هوتي هے.\nوَالحَبُّ ذُو العَصفِچھلكے والے دانے.\nصَلصَالٍكھنكھناتي هوئي مٹي.\nكَالفَخَّارِپكي هوئي سخت مٹي / پتھر كي طرح."],[532,"§الرحمن\ndeeds\nاپنے پانچ آخر میں وفات پانے والے اقرباء کو یادکیجئے اور ا ن کے لئے رحمت کی دعا مانگئے.\nپڑھئے اور اس کامفہوم سامنے رکھ کر اللہ کی عظمت کا احساس پیداکیجئے.\nکوئی گناہ یا دکیجئے جو آپ سے سرزد ہوا ہو پھر کوئی صدقہ کیجئے امید ہے کہ اللہ تعالیٰ اس کے ذریعہ گناہ کا وبال ختم کردے.\nguid\nتمام تر مخلوق اللہ کی محتاج ہے.\nاللہ سے خوف و خشیت کی اہمیت.\nاپنے دل میں روز قیامت کی ہولناکیاں یاد کیجئے.\nrefl\nكُلُّ مَنۡ عَلَيۡهَا فَانٍ ٢٦\nاللہ کے فرمان: (وله الجوار المنشآت في البحر كالأعلام) میں ہلاکت و بربادی سے محفوظ رہنے کےلئے اسباب و ذرائع تیار کرنے کی نعمت کا اعلان ہے۔ اور یہ نعمت گزارے کے لئے روزی کی دوڑ دھوپ کا بھی ذریعہ ہے ۔ سو کشتیوں سے لوگوں کو اسفار میں مدد ملی اور سمندر کی طغیانی سے محفوظ رہتے ہوئے ضروریات کی تکمیل میں سہولت ہوئی۔ یہ بات پیش نظر رہے کہ کشتیوں کی بابت جو یہ(كالأعلام) کہا گیا ہے یعنی پہاڑوں جیسی تو اس سے اس نعمت کی وسعت کا اظہار ہے۔ اب زندگی سے جڑی چیزوں کا بیان ہوگیا تو اسی کے بعد یہ نصیحت بیان ہوئی کہ یہ اسباب و ذرائع اللہ کے مقدر کردہ موت کے فیصلے اور لوگوں کے درمیان حائل نہیں ہوسکتے ۔ جیساکہ مناسب موقع پر قرآن میں تذکیر و موعظت کا طریقہ ہے۔(عاشور:۲۷؍۲۵۲)\nآیتِ کریمہ کی مناسبت اس کی پہلی والی آیت سے کس طرح ہے؟\nكُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ ٢٩\nحضرت ابودرداءنبی صلی اللہ علیہ وسلم سےروایت فرماتے ہیں: اللہ کی شان یہ ہے کہ وہ گناہ بخشتاہے ، پریشانی ہٹاتا ہے، بعض قوموں کو عروج بخشتا ہےاور بعض دوسروں کو پست کر تاہے۔ (القرطبی:۲۰؍۱۳۴)\n(كل يوم هو في شأن)کاکیا مطلب ہے ؟\nسَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ ٣١\nیہاں فارغ ہونے کا یہ معنی نہیں ہے کہ اللہ عمل سے فارغ ہوگا ۔ کیونکہ اللہ کو کوئی کام مشغول ہی نہیں کر سکتا ۔ یہاں دراصل وعید کی شدت بتانی مقصود ہے کہ اللہ مخلوق کا سخت محاسبہ فرمائے گا۔(کیونکہ کسی چیز کو دنیا میں پوری فراغت سے جب آدمی کرتا ہے تو زیادہ پرزور طریقے سے کرتا ہے جیسے کہا جاتاہے میں فرصت سے اس سے نمٹتا ہوں!!!مترجم)\n(سنفرغ لكم أيها الثقلان) سے کیا مراد ہے ؟\nسَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ ٣١\nجنات و انسان کو زمین کے حیوانون کے مقابلے عظیم شان کا حامل ہونے کے سبب‘‘ثقلين’’ کہا گیا۔ اور ایک قول یہ ہےکہ: انہیں ثقلین اس لئے کہا گیا کیونکہ وہ زندہ ہوں تب بھی اور مر جائیں تب بھی زمین کے لئے بوجھ ہیں ۔ جیسا کہ اللہ کے ارشاد میں ہے‘‘اور زمین اپنے بوجھ نکال باہر کرے گی’’ (الزلزلہ:۲) اور جعفر صادق رحمہ اللہ نے فرمایا: کہ انہیں ثقلین کہا گیا کہ دونوں مخلوق گناہ سے بوجھل ہیں ۔(الشوکانی:۵؍۱۳۷)\nجن و انس کو ثقلین کیوں کہاگیا؟\nيُرۡسَلُ عَلَيۡكُمَا شُوَاظٞ مِّن نَّارٖ وَنُحَاسٞ فَلَا تَنتَصِرَانِ ٣٥ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ٣٦\nیعنی تم پرخالص آگ کے شعلے اور دھوئیں پھینکے جائیں گے۔ یعنی اے جن و انس کی جماعت یہ دونوں قبیح ترین چیزیں تمہارے اوپر پھینکی جائیں گی اور تمہیں گھیرلیں گی پھر تمہیں کوئی مدد نہیں مل سکے گی نہ تو خود تم اپنی مددکرسکو گے اور نہ اللہ کے سوا کوئی اور تمہاری مدد کرسکے گا۔ چونکہ بندوں کو خوف دلانا بھی اللہ کی ایک نعمت ہےاورگویا ایک کوڑا ہے جو بلند مقاصد اور اعلیٰ ترین صلاحیتوں کی طرف لے جاتا ہے سو اس بنا پر اللہ نے اس کا بھی احسان جتلایا اور فرمایا: (فبأي آلاء ربكما تكذبان). (السعدی: ۸۳۱)\nجہنم کا تذکرہ مومنوں کے لئے نعمت کیسے ہوسکتاہے ؟\nفَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةٗ كَٱلدِّهَانِ ٣٧\n(دهان)، دهن کی جمع ہے جیسے تیل اور اس طرح کی دوسری چیز یں ہوتی ہیں۔ روز قیامت آسمان کی تشبیہ(دهان)،سے اس لئے دی ہے کہ ہولناکی کی شدت سے آسمان پگھل جائے گا۔ یہ بھی کہا گیا ہے کہ اس کی چمک تیل کی چمک کے مشابہ ہوگی۔ یہ بھی کہا گیا ہےکہ : (دهان)، سرخ چمڑے کو بولتے ہیں۔ (ابن جزی :۲؍۳۹۵)\nآسمان کو (دهان)سے تشبیہ دینےمیں ایک بلیغ سبب ہے ۔ آپ وہ وجہ تسمیہ بیان کیجئے ؟\nفَيَوۡمَئِذٖ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٞ وَلَا جَآنّٞ ٣٩\nاس آیت اور﴿فَوَرَبِّكَ لَنَسَۡٔلَنَّهُمۡ أَجۡمَعِينَ﴾ (الحجر:۹۲) جیسی آیتوں میں تطبیق کی صورت یہ ہے کہ اس آیت میں جو بات ہے وہ ایک الگ مقام کی بات ہے۔اور سوال قیامت کے موقف میں سے کسی دوسرے موقف میں ہوگا۔ یہ بھی کہا گیاہے کہ سوال کی جو بات آیت میں ہے وہ گناہوں کی بابت استفہام کی قبیل کا سوال نہیں ہے کیونکہ اللہ تعالیٰ نے اعمال کو شمار کررکھا ہے اور بندوں کے خلاف انہیں محفوظ کررکھا ہے ۔ البتہ سوال زجر وتوبیخ کے واسطے کیا جائے گا۔(الشوکانی :۵؍۱۳۸)\nاس آیت اور اللہ کے فرمان (فوربك لنسألهم أجمعين) کے درمیان ہم کیسے تطبیق دے سکتےہیں ؟\nwords\nمَرَجَ البَحرَينِدو سمندر ملاديے؛ ايك ميٹھا؛ اورايك كھارا.\nبَرزَخٌركاوٹ.\nالجَوَارِبڑي كشتياں.\nفَانٍهلاك هونے والا.\nفِي شَأنٍكسي كام ميں- وه عزت اور ذلت ديتا هے۔زنده كرتا او رمارتا هے.\nتَنفُذُوااگر تم بھاگ سكو.\nشُوَاظٌخالص شعلے.\nكَالدِّهَانِجيسے ابلا هوا تيل۔ جيسے سرخ چمڑي.\nبِسِيمَاهُمان كي نشانيوں سے."],[533,"§الرحمن\ndeeds\nکوئی ایسا عمل کیجئے جو اللہ سے آپ کے خوف پر دلالت کرے.\nاپنے کسی جاننے والے سے جہنم کی بابت گفتگو کریں یا کوئی مقالہ لکھیں جس میں قیامت کی ہولناکی کا بیان ہو اور اس ہولناکی پر آپ کی تصدیق کا تذکرہ بھی رہے.\nکسی کاخیال کیجئے جس نے آپ کے ساتھ بھلائی کی ہو۔ اور اسے جَزَاكَ اللٰهُ خَيْرًا کہیں اگر ممکن ہو تو اسےکوئی ہدیہ بھی دیں یہ اچھی بات ہوگی.\nguid\nعذاب جہنم سے اللہ کی پناہ.\nاللہ سے خوف کی اہمیت.\nاللہ کا فضل اور بندو ں پر اس کا کرم اور اس کی رحمت.\nrefl\nهَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ ٤٣ يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانٖ ٤٤ فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ٤٥\nدراصل نافرمانوں اورمجرموں کو سزا دینا اور متقیوں کو نازونعمت عطا کرنا مخلوق پر اللہ کی فضل و رحمت اور عدل و مہربانی ہے۔ اسی طرح انہیں اپنے عذاب اور مصائب سے ڈرانا کہ وہ شرک و نافرمانی میں مبتلا نہ ہوں اور ان سے باز آجائیں یہ بھی اللہ کی مہربانی ہے ۔تو اب اللہ نے اپنی مخلوق پر احسان جتلاتے ہوئے فرمایا: (فبأي آلاء ربكما تكذبان). (ابن کثیر :۴؍۲۷۸)\nاللہ نے جہنم میں مجرمین کو عذاب دیئے جانے کا ذکر کیا ہے پھر ان پر اپنے اس فرمان (فبأي آلاء ربكما تكذبان) کےذریعہ احسان جتلایا ۔سوال یہ ہے کہ اپنے بندوں پر مجرمین کے عذاب کا احسان جتلانا کیا معنی رکھتا ہے؟\nوَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ ٤٦\nامام راغب رحمہ اللہ فرماتے ہیں: اللہ کے خوف سے مراد دل میں جو رعب پیدا ہوجاتا ہے وہ نہیں ہے جیسا کہ شیر سے خوف محسوس ہوتا ہے ۔ بلکہ یہاں مراد گناہوں سے رکنا اور اطاعت کےکام کرنا ہے۔ اسی لئےکہا گیا ہے : جو گناہوں کا تارک نہیں ہے اسے خائف یعنی ڈرنے والا نہیں کہہ سکتے ۔ (الألوسی :۱۴؍۱۱۵)\nاللہ کے یہاں کھڑے ہونےسے خوف کس طرح ہوتا ہے؟\nمُتَّكِـِٔينَ عَلَىٰ فُرُشِۢ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقٖۚ\nان بچھونوں کا حسن اور ان کی خوبیاں صرف اللہ کو پتہ ہیں۔ یہاں تک کہ اس کے اندرونی استر عالیشان ریشم کے ہوں گے اور استبرق سب سے شاندار اور اچھا ریشم ہوتا ہے پھر سوچئے کہ ان کی ظاہری شکل کیسے ہوگی جو ان کے بدن سے لگتا ہوگا۔(السعدی:۸۳۱)\nبچھونے کے استروں کی خوبصورتی سے کیا پتہ چلتا ہے؟\nوَجَنَى ٱلۡجَنَّتَيۡنِ دَانٖ ٥٤\n(جني) کہتے ہیں اسے جو پھلوں سے چنا جائے ۔ اور دان کا معنی قریب ہے ۔ روایت ہے کہ جنت میں انسان کسی بھی حال میں رہے میوہ چن سکتاہے کھڑا ہو ،بیٹھا ہو لیٹا ہو جس حال میں بھی ہو۔ کیونکہ جب وہ چاہے گا پھل اس کے پاس جھک جائیں گے ۔(ابن جزی:۲؍۳۹۶)\nبندوں کے لئے پھلوں کی قربت واضح کیجئے ؟\nكَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ ٥٨\nیاقوت و مرجان سے تشبیہ پسندیدہ سرخ رنگ کے سبب ہے، یہ سرخی گالوں کی سرخی ہوگی جیسا کہ گال کو گلاب سے تشبیہ دی جاتی ہے ۔ اور سرخ کا اطلاق گورے پر بھی ہوتا ہے اسی معنی میں ایک حدیث وارد ہے ‘‘بُعِثْتُ اِلَي الْاَحْمَرِ وَالْاَسْوَدِ’’ ‘‘میں کالے گورے تمام کی طرف بھیجا گیا ہوں’’ (ابن عاشور:۲؍۲۷۰)\nجنت کی عورتوں کی تشبیہ یاقوت و مرجان سے کیوں دی گئی ہے؟\nهَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ ٦٠\nمطلب یہ ہے کہ جس نے اللہ کی اطاعت کرکے احسان کیا اللہ اس کو جنت دے کر اس پر احسان کرے گا۔ اور یہ بھی ممکن ہے کہ یہاں احسان سے مراد وہی احسان ہو جس کے بارے میں حضرت جبریل نے اللہ کے رسول سے سوال کیاتھا توآپ نے جواب میں کہا تھا “اللہ کی عبادت ایسے کرو گویا کہ تم اس کو دیکھ رہے ہو اگر تم نہیں دیکھ پا رہے ہو تو وہ تم کو دیکھ رہا ہے”یہ مراقبہ اور مشاہدہ (اللہ کی نگرانی کے تصور) کا (بلند) مقام ہے، پس اللہ نے اس احسان کا بدلہ ان دونوں جنتوں سے دیا۔ اس کی تائید اس بات سے بھی ہوتی ہے کہ ان دونوں جنتوں کو بلند و بالا مقام والوں کے لئے مقررکیا، اس کے علاوہ دیگر دو جنتوں کو اس سے کم درجہ والوں کے لئے مقررکیا۔ (ابن جزی:۲؍۳۹۶)\nدونوں جگہوں پر احسان سے کیامراد ہے؟\nهَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ ٦٠\nپہلی دو جنتوں کی بابت (هل جزاء الإحسان إلا الإحسان) فرمایایعنی احسان کا بدلہ احسان ہی ہوگا۔ اس سے یہ پتہ چلتاہےکہ پہلی دو جنتیں محسنین کے واسطے ہیں۔اور یہ بات آخری دو جنتوں کی بابت نہیں فرمائی۔ اس سےپہلی دو جنتوں کی دوسری دو جنتوں پر فضیلت ثابت ہوتی ہے ۔ اور یہ پہلی دو جنتیں انبیاء ، صدیقین جیسے مقربین اور اللہ کے خاص نیک بندوں کے لئے تیار کی گئی ہیں اور آخری دو جنتیں عام مومنین کے لئے ہیں ۔(السعدی:۸۳۲)\nپہلی دو جنتوں کے بارے میں اللہ کا قول (هل جزاء الإحسان إلا الإحسان) کس بات پر دلالت کرتا ہے؟ اوریہ بات آخری دو جنتوں کے بارےمیں کیوں نہیں ہے ؟\nwords\nحَمِيمٍ آنٍانتهائي گرم پاني.\nبَطَائِنُهَااس كے اندر كا لباس.\nإِستَبرَقٍموٹا ريشم.\nدانجھکے ہوئے.\nقَاصِرَاتُ الطَّرفِاپني نظروں كو جھكانے والياں۔ اپنے شوهروں كے علاوه كسي كو نه ديكھيں گي.\nيَطمِثهُنَّان سے وطي كي هوگي/ ان كو چھوا هوگا.\nمُدهَآمَّتَانِانتهائي سبز.\nنَضَّاخَتَانِپاني كے دو فوارے."]])